import React, { useState } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, MessageSquare, Edit2, Plus, Trash2, X, Check } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Specialist>>({});

  const handleEdit = (s: Specialist) => {
    setEditingId(s.id);
    setEditForm(s);
  };

  const handleSave = () => {
    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...editForm } as Specialist : s));
      setEditingId(null);
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setEditForm({});
  };

  const categories = Object.values(SpecialistCategory);

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">Specialistų Kontaktai</h2>
          <p className="text-gray-500">Mokyklos pagalbos specialistų sąrašas ir jų pasiekiamumas.</p>
        </div>
        <button className="bg-green-600 text-white px-4 py-2 rounded-lg flex items-center space-x-2 hover:bg-green-700 transition">
          <Plus size={18} />
          <span>Pridėti specialistą</span>
        </button>
      </div>

      <div className="grid grid-cols-1 gap-8">
        {categories.map(category => (
          <div key={category} className="space-y-4">
            <h3 className="text-lg font-semibold border-b pb-2 text-green-800">{category}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {specialists.filter(s => s.category === category).map(s => (
                <div key={s.id} className="bg-white p-5 rounded-xl border shadow-sm hover:shadow-md transition group">
                  {editingId === s.id ? (
                    <div className="space-y-2">
                      <input 
                        className="w-full border rounded px-2 py-1 text-sm" 
                        value={editForm.name} 
                        onChange={e => setEditForm({...editForm, name: e.target.value})}
                        placeholder="Vardas Pavardė"
                      />
                      <input 
                        className="w-full border rounded px-2 py-1 text-sm" 
                        value={editForm.classes} 
                        onChange={e => setEditForm({...editForm, classes: e.target.value})}
                        placeholder="Kuruojamos klasės"
                      />
                      <input 
                        className="w-full border rounded px-2 py-1 text-sm" 
                        value={editForm.phone} 
                        onChange={e => setEditForm({...editForm, phone: e.target.value})}
                        placeholder="Telefonas"
                      />
                      <input 
                        className="w-full border rounded px-2 py-1 text-sm" 
                        value={editForm.email} 
                        onChange={e => setEditForm({...editForm, email: e.target.value})}
                        placeholder="El. paštas"
                      />
                      <div className="flex space-x-2 pt-2">
                        <button onClick={handleSave} className="bg-green-600 text-white px-2 py-1 rounded text-xs flex items-center"><Check size={14} /> Išsaugoti</button>
                        <button onClick={handleCancel} className="bg-gray-200 text-gray-700 px-2 py-1 rounded text-xs flex items-center"><X size={14} /> Atšaukti</button>
                      </div>
                    </div>
                  ) : (
                    <>
                      <div className="flex justify-between items-start">
                        <div>
                          <h4 className="font-bold text-gray-900">{s.name}</h4>
                          <p className="text-xs text-gray-500 mb-2">{s.classes}</p>
                        </div>
                        <button 
                          onClick={() => handleEdit(s)}
                          className="opacity-0 group-hover:opacity-100 transition text-blue-600 hover:text-blue-800"
                        >
                          <Edit2 size={16} />
                        </button>
                      </div>

                      <div className="space-y-1 text-sm text-gray-600 mb-4">
                        <div className="flex items-center space-x-2">
                          <Phone size={14} /> <span>{s.phone}</span>
                        </div>
                        <div className="flex items-center space-x-2">
                          <Mail size={14} /> <span className="truncate">{s.email || '-'}</span>
                        </div>
                        <div className="text-xs font-semibold bg-gray-100 inline-block px-2 py-0.5 rounded">
                          Kabinetas: {s.office}
                        </div>
                      </div>

                      <div className="flex space-x-2">
                        <a href={`tel:${s.phone}`} className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition" title="Skambinti">
                          <Phone size={18} />
                        </a>
                        <a href={`mailto:${s.email}`} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition" title="Gmail">
                          <Mail size={18} />
                        </a>
                        <a 
                          href={`https://chat.google.com/`} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="p-2 bg-green-50 text-green-600 rounded-lg hover:bg-green-100 transition" 
                          title="Google Chat"
                        >
                          <MessageSquare size={18} />
                        </a>
                      </div>
                    </>
                  )}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ContactsTab;

import React, { useState } from 'react';
import { EmailTemplate } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Plus, Send, Copy, Edit3, Save, Trash2, ChevronRight } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [templates, setTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');

  const selectedTemplate = templates.find(t => t.id === selectedId) || templates[0];

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const filteredTemplates = templates.filter(t => 
    t.title.toLowerCase().includes(search.toLowerCase()) || 
    t.recipientType.toLowerCase().includes(search.toLowerCase())
  );

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    alert('Nukopijuota į iškarpinę!');
  };

  const openInGmail = () => {
    const mailto = `mailto:?subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-160px)]">
      {/* Sidebar - List */}
      <div className="lg:col-span-1 border rounded-xl bg-white flex flex-col overflow-hidden">
        <div className="p-4 border-b">
          <div className="relative">
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Ieškoti šablonų..."
              className="w-full pl-10 pr-4 py-2 border rounded-lg focus:ring-2 focus:ring-green-500 outline-none text-sm"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {filteredTemplates.map(t => (
            <button
              key={t.id}
              onClick={() => setSelectedId(t.id)}
              className={`w-full text-left p-4 border-b transition-colors hover:bg-gray-50 flex items-center justify-between group ${
                selectedId === t.id ? 'bg-green-50 border-l-4 border-l-green-600' : ''
              }`}
            >
              <div>
                <h4 className="font-semibold text-sm text-gray-900">{t.title}</h4>
                <p className="text-xs text-gray-500 mt-1">{t.recipientType}</p>
              </div>
              <ChevronRight size={16} className={`text-gray-400 group-hover:translate-x-1 transition-transform ${selectedId === t.id ? 'text-green-600' : ''}`} />
            </button>
          ))}
        </div>
        <button className="p-4 border-t text-green-700 font-semibold text-sm flex items-center justify-center space-x-2 hover:bg-green-50 transition">
          <Plus size={18} />
          <span>Naujas šablonas</span>
        </button>
      </div>

      {/* Editor Area */}
      <div className="lg:col-span-2 flex flex-col space-y-4">
        <div className="bg-white border rounded-xl flex-1 flex flex-col p-6 shadow-sm">
          <div className="mb-4">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Šablono Pavadinimas</label>
            <input
              type="text"
              className="w-full border rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 outline-none font-semibold"
              value={selectedTemplate.title}
              onChange={e => handleUpdate('title', e.target.value)}
            />
          </div>

          <div className="mb-4">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Laiško Tema</label>
            <input
              type="text"
              className="w-full border rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 outline-none"
              value={selectedTemplate.subject}
              onChange={e => handleUpdate('subject', e.target.value)}
            />
          </div>

          <div className="flex-1 flex flex-col">
            <label className="block text-xs font-semibold text-gray-500 uppercase mb-1">Turinys</label>
            <textarea
              className="flex-1 w-full border rounded-lg px-4 py-3 focus:ring-2 focus:ring-green-500 outline-none resize-none font-serif leading-relaxed"
              value={selectedTemplate.body}
              onChange={e => handleUpdate('body', e.target.value)}
            />
          </div>

          <div className="mt-6 flex flex-wrap gap-3">
            <button 
              onClick={openInGmail}
              className="bg-green-600 text-white px-6 py-2 rounded-lg font-medium flex items-center space-x-2 hover:bg-green-700 transition shadow-md"
            >
              <Send size={18} />
              <span>Siųsti per Gmail / El. dienyną</span>
            </button>
            <button 
              onClick={copyToClipboard}
              className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg font-medium flex items-center space-x-2 hover:bg-gray-200 transition"
            >
              <Copy size={18} />
              <span>Kopijuoti</span>
            </button>
            <button className="ml-auto text-red-600 p-2 hover:bg-red-50 rounded-lg transition" title="Ištrinti">
              <Trash2 size={20} />
            </button>
          </div>
        </div>

        <div className="bg-amber-50 border border-amber-200 p-4 rounded-xl flex items-start space-x-3">
          <Edit3 className="text-amber-600 mt-0.5" size={20} />
          <div>
            <h5 className="text-sm font-bold text-amber-800">Redagavimo patarimas</h5>
            <p className="text-xs text-amber-700 mt-1">
              Naudokite skliaustelius <code>[Vardas Pavardė]</code> nurodyti vietoms, kurias reikia užpildyti siunčiant laišką.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TemplatesTab;

