import TemplatesTab from './components/TemplatesTab';
import ScenariosTab from './components/ScenariosTab';
import { Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard setActiveTab={setActiveTab} />;
      case 'schemes': return <SchemesTab />;
      case 'contacts': return <ContactsTab />;
      case 'templates': return <TemplatesTab />;
      case 'scenarios': return <ScenariosTab />;
      default: return <Dashboard setActiveTab={setActiveTab} />;
    }
  };

  const getTitle = () => {
    switch (activeTab) {
      case 'dashboard': return 'Apžvalga';
      case 'schemes': return 'Pagalbos schemos';
      case 'contacts': return 'Specialistų kontaktai';
      case 'templates': return 'Laiškų šablonai';
      case 'scenarios': return 'Situacijų valdymas';
      default: return 'VAP pagalbos sistema';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 flex">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      {/* Mobile Menu */}
      <div className={`fixed inset-y-0 left-0 w-64 bg-white z-50 transform transition-transform md:hidden ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 border-b flex justify-between items-center">
          <h1 className="text-xl font-bold text-green-700">VAP pagalba</h1>
          <button onClick={() => setIsMobileMenuOpen(false)}><X /></button>
        </div>
        <nav className="p-4 space-y-2">
          {[
            { id: 'dashboard', label: 'Apžvalga' },
            { id: 'schemes', label: 'Schemos' },
            { id: 'contacts', label: 'Kontaktai' },
            { id: 'templates', label: 'Šablonai' },
            { id: 'scenarios', label: 'Situacijos' }
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveTab(item.id); setIsMobileMenuOpen(false); }}
              className={`w-full text-left px-4 py-3 rounded-lg ${activeTab === item.id ? 'bg-green-50 text-green-700 font-bold' : 'text-gray-600'}`}
            >
              {item.label}
            </button>
          ))}
        </nav>
      </div>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="bg-white border-b h-16 sticky top-0 z-30 px-6 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <button className="md:hidden" onClick={() => setIsMobileMenuOpen(true)}>
              <Menu />
            </button>
            <h2 className="text-lg font-bold text-gray-800">{getTitle()}</h2>
          </div>
          <div className="flex items-center space-x-4">
            <div className="hidden sm:flex items-center space-x-2 px-3 py-1.5 bg-green-50 rounded-full border border-green-100">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <span className="text-xs font-bold text-green-700">Sistema aktyvi</span>
            </div>
          </div>
        </header>

        <div className="p-6 flex-1 overflow-y-auto max-w-7xl mx-auto w-full">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

