                            target="_blank" 
                            rel="noopener noreferrer" 
                            className="flex-1 py-2 bg-green-50 text-green-600 rounded-xl hover:bg-green-600 hover:text-white transition-all flex items-center justify-center" 
                            title="Google Chat"
                          >
                            <MessageSquare size={16} />
                          </a>
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ContactsTab;

import React, { useState, useMemo } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, Trash2, Save, X, AlertCircle } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [templates, setTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');
  const [isAdding, setIsAdding] = useState(false);

  // Draft state for the currently selected template to allow "Save/Cancel" pattern
  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === selectedId) || templates[0], 
    [templates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleDelete = (id: string) => {
    if (templates.length <= 1) {
      alert("Negalima ištrinti paskutinio šablono.");
      return;
    }
    if (window.confirm('Ar tikrai norite ištrinti šį šabloną?')) {
      const newTemplates = templates.filter(t => t.id !== id);
      setTemplates(newTemplates);
      setSelectedId(newTemplates[0].id);
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };
    setTemplates([newTemplate, ...templates]);
    setSelectedId(newId);
    setIsAdding(false);
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Lankomumas', 'Telefonai', 'Patyčios', 'Uniformos', 
    'Mokymasis / SUP', 'Sveikata', 'Incidentai / krizės', 'Administraciniai', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return templates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase()) ||
                           t.body.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [templates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    alert('Tekstas nukopijuotas! Galite įklijuoti į Mano Dienynas pranešimų langą.');
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[calc(100vh-180px)]">
      {/* Kairysis sąrašas */}
      <div className="lg:col-span-4 border border-gray-200 rounded-xl bg-white flex flex-col overflow-hidden shadow-sm">
        <div className="p-4 border-b border-gray-100 space-y-3">
          <div className="flex items-center space-x-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="Ieškoti šablonų..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 outline-none text-sm bg-white text-gray-900"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>
            <button 
              onClick={handleAddTemplate}
              className="p-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition shadow-sm"
              title="Pridėti naują šabloną"
            >
              <Plus size={20} />
            </button>
          </div>
          <div className="flex overflow-x-auto pb-1 space-x-2 scrollbar-hide">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`flex-shrink-0 px-3 py-1 rounded-full text-[10px] font-bold uppercase border transition-all ${
                  activeCategory === cat 
                    ? 'bg-green-600 text-white border-green-600' 
                    : 'bg-gray-50 text-gray-600 hover:bg-gray-100 border-gray-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {filteredTemplates.length > 0 ? (
            filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-4 border-b border-gray-50 transition-colors hover:bg-gray-50 flex items-center justify-between group ${
                  selectedId === t.id ? 'bg-green-50 border-l-4 border-l-green-600' : ''
                }`}
              >
                <div className="min-w-0">
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="text-[10px] font-bold uppercase text-green-700 bg-green-100 px-1.5 py-0.5 rounded">
                      {t.category}
                    </span>
                  </div>
                  <h4 className="font-semibold text-sm text-gray-900 truncate">{t.title}</h4>
                </div>
                <ChevronRight size={16} className={`text-gray-400 group-hover:translate-x-1 transition-transform ${selectedId === t.id ? 'text-green-600' : ''}`} />
              </button>
            ))
          ) : (
            <div className="p-10 text-center">
              <AlertCircle className="mx-auto text-gray-300 mb-2" size={32} />
              <p className="text-gray-400 text-sm">Šablonų nerasta</p>
            </div>
          )}
        </div>
      </div>

      {/* Dešinysis redagavimo langas */}
      <div className="lg:col-span-8 flex flex-col min-h-0">
        <div className="bg-white border border-gray-200 rounded-xl flex-1 flex flex-col p-6 shadow-sm overflow-hidden relative">

          <div className="flex justify-between items-start mb-6">
            <div className="flex-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Šablono pavadinimas</label>
              <input
                type="text"
                className="text-lg font-bold text-gray-900 border-b border-transparent hover:border-gray-200 focus:border-green-500 outline-none bg-transparent w-full"
                value={selectedTemplate.title}
                onChange={e => handleUpdate('title', e.target.value)}
              />
            </div>
            <button 
              onClick={() => handleDelete(selectedTemplate.id)}
              className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
              title="Ištrinti šabloną"
            >
              <Trash2 size={20} />
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
            <div>
              <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Kategorija</label>
              <select 
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 font-medium"
                value={selectedTemplate.category}
                onChange={e => handleUpdate('category', e.target.value as TemplateCategory)}
              >
                {categories.filter(c => c !== 'Visi').map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Gavėjo tipas</label>
              <select 
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 font-medium"
                value={selectedTemplate.recipientType}
                onChange={e => handleUpdate('recipientType', e.target.value as any)}
              >
                <option value="Tėvai">Tėvai</option>
                <option value="Mokytojas">Mokytojas</option>
                <option value="Darbuotojas">Darbuotojas</option>
                <option value="Savivaldybė">Savivaldybė</option>
              </select>
            </div>
          </div>

          <div className="mb-4">
            <label className="text-xs font-bold text-gray-500 uppercase block mb-1">El. laiško tema</label>
            <input
              type="text"
              className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 outline-none font-medium bg-white text-gray-900"
              value={selectedTemplate.subject}
              onChange={e => handleUpdate('subject', e.target.value)}
              placeholder="Įrašykite temą..."
            />
          </div>

          <div className="flex-1 flex flex-col min-h-0">
            <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Turinys</label>
            <textarea
              className="flex-1 w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-green-500 outline-none font-serif leading-relaxed text-gray-900 bg-white min-h-[200px]"
              value={selectedTemplate.body}
              onChange={e => handleUpdate('body', e.target.value)}
              placeholder="Rašykite laišką čia..."
            />
          </div>

          <div className="mt-6 flex flex-col sm:flex-row gap-3">
             <button 
              onClick={() => alert('Pakeitimai išsaugoti lokaliai.')}
              className="bg-gray-100 text-gray-700 px-6 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-gray-200 transition"
            >
              <Save size={18} />
              <span>Išsaugoti pakeitimus</span>
            </button>
            <div className="flex-1 flex gap-3">
              <button 
                onClick={openInGmail}
                className="flex-1 bg-red-600 text-white px-4 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-red-700 transition shadow-sm"
              >
                <Mail size={18} />
                <span>Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className="flex-1 bg-green-600 text-white px-4 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-green-700 transition shadow-sm"
              >
                <Copy size={18} />
                <span>Kopijuoti</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TemplatesTab;

import React, { useState } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, MessageSquare, Edit2, Plus, Trash2, X, Check, AlertCircle, AlertTriangle } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const initialFormState: Partial<Specialist> = {
    name: '',
    category: SpecialistCategory.SOCIALINIAI,
    classes: '',
    phone: '',
    office: '',
    email: ''
  };

  const [form, setForm] = useState<Partial<Specialist>>(initialFormState);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = (data: Partial<Specialist>) => {
    const newErrors: Record<string, string> = {};
    if (!data.name?.trim()) newErrors.name = 'Vardas yra privalomas';

    if (data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) {
      newErrors.email = 'Neteisingas el. pašto formatas';
    }

    if (data.phone && !/^(\+370|8|0)6\d{7}$|^(\+370|8|0)5\d{7}$|^-$/.test(data.phone.replace(/\s/g, ''))) {
      if (data.phone !== '-') {
        newErrors.phone = 'Neteisingas telefono formatas (pvz. +3706...)';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleEdit = (s: Specialist) => {
    setEditingId(s.id);
    setForm(s);
    setErrors({});
  };

  const handleSave = () => {
    if (!validate(form)) return;

    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...form } as Specialist : s));
      setEditingId(null);
    } else {
      const newSpecialist: Specialist = {
        ...form as Specialist,
        id: Date.now().toString(),
      };
      setSpecialists(prev => [...prev, newSpecialist]);
      setIsAdding(false);
    }
    setForm(initialFormState);
  };

  const initiateDelete = (id: string) => {
    setDeleteConfirmId(id);
  };

  const confirmDelete = () => {
    if (deleteConfirmId) {
      setSpecialists(prev => prev.filter(s => s.id !== deleteConfirmId));
      setDeleteConfirmId(null);
    }
  };

  const handleCancel = () => {
    setEditingId(null);
    setIsAdding(false);
    setForm(initialFormState);
    setErrors({});
  };

  const categories = Object.values(SpecialistCategory);

  const renderForm = (isNew: boolean = false) => (
    <div className="space-y-3 p-2 bg-gray-50 rounded-xl border border-gray-200">
      <div className="grid grid-cols-1 gap-3">
        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase">Vardas Pavardė</label>
          <input 
            className={`w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 ${errors.name ? 'border-red-500' : 'border-gray-300'}`}
            value={form.name} 
            onChange={e => setForm({...form, name: e.target.value})}
            placeholder="Pvz. Jonas Jonaitis"
          />
          {errors.name && <p className="text-[10px] text-red-500 mt-1 flex items-center"><AlertCircle size={10} className="mr-1"/>{errors.name}</p>}
        </div>

        {isNew && (
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase">Kategorija</label>
            <select 
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900"
              value={form.category}
              onChange={e => setForm({...form, category: e.target.value as SpecialistCategory})}
            >
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
        )}

        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase">Kuruojamos klasės / Pareigos</label>
          <input 
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900" 
            value={form.classes} 
            onChange={e => setForm({...form, classes: e.target.value})}
            placeholder="Pvz. 1-4 klasės"
          />
        </div>

        <div className="grid grid-cols-2 gap-2">
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase">Telefonas</label>
            <input 
              className={`w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 ${errors.phone ? 'border-red-500' : 'border-gray-300'}`}
              value={form.phone} 
              onChange={e => setForm({...form, phone: e.target.value})}
              placeholder="+370..."
            />
            {errors.phone && <p className="text-[10px] text-red-500 mt-1">{errors.phone}</p>}
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase">Kabinetas</label>
            <input 
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900"
              value={form.office} 
              onChange={e => setForm({...form, office: e.target.value})}
              placeholder="Kab. nr."
            />
          </div>
        </div>

        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase">El. paštas</label>
          <input 
            className={`w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 ${errors.email ? 'border-red-500' : 'border-gray-300'}`}
            value={form.email} 
            onChange={e => setForm({...form, email: e.target.value})}
            placeholder="vardas.pavarde@antakalnio.lt"
          />
          {errors.email && <p className="text-[10px] text-red-500 mt-1">{errors.email}</p>}
        </div>
      </div>

      <div className="flex space-x-2 pt-2">
        <button 
          onClick={handleSave} 
          className="flex-1 bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center space-x-1 hover:bg-green-700 transition"
        >
          <Check size={16} /> 
          <span>Išsaugoti</span>
        </button>
        <button 
          onClick={handleCancel} 
          className="bg-gray-200 text-gray-700 px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center space-x-1 hover:bg-gray-300 transition"
        >
          <X size={16} /> 
          <span>Atšaukti</span>
        </button>
      </div>
    </div>
  );

  const deleteTarget = deleteConfirmId ? specialists.find(s => s.id === deleteConfirmId) : null;

  return (
    <div className="space-y-8 pb-10">
      {/* Delete Confirmation Modal */}
      {deleteConfirmId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-center w-12 h-12 rounded-full bg-red-100 text-red-600 mx-auto mb-4">
              <AlertTriangle size={24} />
            </div>
            <h3 className="text-center text-lg font-bold text-gray-900 mb-2">Ištrinti kontaktą?</h3>
            <p className="text-center text-sm text-gray-500 mb-6">
              Ar tikrai norite ištrinti <span className="font-bold text-gray-700">{deleteTarget?.name}</span>? Šio veiksmo atšaukti nebus galima.
            </p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setDeleteConfirmId(null)}
                className="py-2.5 rounded-xl font-bold text-sm text-gray-700 bg-gray-100 hover:bg-gray-200 transition"
              >
                Atšaukti
              </button>
              <button 
                onClick={confirmDelete}
                className="py-2.5 rounded-xl font-bold text-sm text-white bg-red-600 hover:bg-red-700 transition shadow-sm"
              >
                Ištrinti
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Specialistų Kontaktai</h2>
          <p className="text-sm text-gray-500">Mokyklos pagalbos specialistų sąrašas ir jų pasiekiamumas.</p>
        </div>
        {!isAdding && (
          <button 
            onClick={() => { setIsAdding(true); setEditingId(null); setForm(initialFormState); }}
            className="bg-green-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center space-x-2 hover:bg-green-700 transition shadow-sm"
          >
            <Plus size={20} />
            <span>Pridėti specialistą</span>
          </button>
        )}
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl border-2 border-green-500 shadow-lg max-w-2xl">
          <h3 className="text-lg font-bold mb-4 text-green-800 flex items-center">
            <Plus size={20} className="mr-2" />
            Naujo specialisto pridėjimas
          </h3>
          {renderForm(true)}
        </div>
      )}

      <div className="grid grid-cols-1 gap-10">
        {categories.map(category => {
          const filteredSpecialists = specialists.filter(s => s.category === category);
          if (filteredSpecialists.length === 0 && !isAdding) return null;

          return (
            <div key={category} className="space-y-4">
              <h3 className="text-sm font-bold uppercase tracking-widest text-green-800 border-b-2 border-green-100 pb-2 flex items-center">
                <span className="bg-green-50 px-3 py-1 rounded-lg">{category}</span>
                <span className="ml-3 text-[10px] text-gray-400 font-normal">({filteredSpecialists.length})</span>
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                {filteredSpecialists.map(s => (
                  <div key={s.id} className={`bg-white p-5 rounded-2xl border transition-all group relative ${editingId === s.id ? 'ring-2 ring-green-500 shadow-lg border-transparent' : 'hover:shadow-md hover:border-green-200 shadow-sm'}`}>
                    {editingId === s.id ? (
                      renderForm()
                    ) : (
                      <>
                        <div className="flex justify-between items-start mb-3">
                          <div className="min-w-0">
                            <h4 className="font-bold text-gray-900 truncate pr-2">{s.name}</h4>
                            <p className="text-[10px] font-bold text-green-600 uppercase tracking-tight mt-0.5">{s.classes}</p>
                          </div>
                          <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => handleEdit(s)}
                              className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition"
                              title="Redaguoti"
                            >
                              <Edit2 size={16} />
                            </button>
                            <button 
                              onClick={() => initiateDelete(s.id)}
                              className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition"
                              title="Ištrinti"
                            >
                              <Trash2 size={16} />
                            </button>
                          </div>
                        </div>

                        <div className="space-y-2 text-sm text-gray-600 mb-5">
                          <div className="flex items-center space-x-3 group/item">
                            <div className="p-1.5 bg-gray-50 rounded-md group-hover/item:bg-blue-50 group-hover/item:text-blue-600 transition">
                              <Phone size={14} />
                            </div>
                            <span className="font-medium text-xs">{s.phone}</span>
                          </div>
                          <div className="flex items-center space-x-3 group/item">
                            <div className="p-1.5 bg-gray-50 rounded-md group-hover/item:bg-red-50 group-hover/item:text-red-600 transition">
                              <Mail size={14} />
                            </div>
                            <span className="truncate font-medium text-xs">{s.email || '-'}</span>
                          </div>
                          <div className="mt-3 flex items-center space-x-2">
                             <span className="text-[10px] font-bold text-gray-400 uppercase">Kabinetas:</span>
                             <span className="text-xs font-bold text-gray-700 bg-gray-100 px-2 py-0.5 rounded-full border border-gray-200">
                               {s.office}
                             </span>
                          </div>
                        </div>

                        <div className="flex gap-2 border-t pt-4">
                          <a 
                            href={`tel:${s.phone.replace(/\s/g, '')}`} 
                            className="flex-1 py-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all flex items-center justify-center" 
                            title="Skambinti"
                          >
