import React, { useState, useMemo } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, Trash2, Save, X, AlertCircle } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [templates, setTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');

  // Draft state for the currently selected template
  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === selectedId) || templates[0], 
    [templates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleDelete = (id: string) => {
    if (templates.length <= 1) {
      alert("Negalima ištrinti paskutinio šablono.");
      return;
    }
    if (window.confirm('Ar tikrai norite ištrinti šį šabloną?')) {
      const newTemplates = templates.filter(t => t.id !== id);
      setTemplates(newTemplates);
      setSelectedId(newTemplates[0].id);
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };

    // Add to top of the list
    setTemplates(prev => [newTemplate, ...prev]);
    setSelectedId(newId);

    // Clear filters to ensure the new template is visible
    setSearch('');
    setActiveCategory('Visi');
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Lankomumas', 'Telefonai', 'Patyčios', 'Uniformos', 
    'Mokymasis / SUP', 'Sveikata', 'Incidentai / krizės', 'Administraciniai', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return templates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase()) ||
                           t.body.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [templates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    alert('Tekstas nukopijuotas! Galite įklijuoti į Mano Dienynas pranešimų langą.');
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[calc(100vh-180px)]">
      {/* Kairysis sąrašas */}
      <div className="lg:col-span-4 border border-gray-200 rounded-xl bg-white flex flex-col overflow-hidden shadow-sm">
        <div className="p-4 border-b border-gray-100 space-y-3">
          <div className="flex items-center space-x-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
              <input
                type="text"
                placeholder="Ieškoti šablonų..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 outline-none text-sm bg-white text-gray-900"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>
            <button 
              onClick={handleAddTemplate}
              className="px-3 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition shadow-sm flex items-center space-x-1 whitespace-nowrap"
              title="Sukurti naują šabloną"
            >
              <Plus size={18} />
              <span className="text-xs font-bold hidden sm:inline">Naujas</span>
            </button>
          </div>
          <div className="flex overflow-x-auto pb-1 space-x-2 scrollbar-hide">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`flex-shrink-0 px-3 py-1 rounded-full text-[10px] font-bold uppercase border transition-all ${
                  activeCategory === cat 
                    ? 'bg-green-600 text-white border-green-600' 
                    : 'bg-gray-50 text-gray-600 hover:bg-gray-100 border-gray-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
        <div className="flex-1 overflow-y-auto">
          {filteredTemplates.length > 0 ? (
            filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-4 border-b border-gray-50 transition-colors hover:bg-gray-50 flex items-center justify-between group ${
                  selectedId === t.id ? 'bg-green-50 border-l-4 border-l-green-600' : ''
                }`}
              >
                <div className="min-w-0">
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="text-[10px] font-bold uppercase text-green-700 bg-green-100 px-1.5 py-0.5 rounded">
                      {t.category}
                    </span>
                  </div>
                  <h4 className="font-semibold text-sm text-gray-900 truncate">{t.title}</h4>
                </div>
                <ChevronRight size={16} className={`text-gray-400 group-hover:translate-x-1 transition-transform ${selectedId === t.id ? 'text-green-600' : ''}`} />
              </button>
            ))
          ) : (
            <div className="p-10 text-center">
              <AlertCircle className="mx-auto text-gray-300 mb-2" size={32} />
              <p className="text-gray-400 text-sm">Šablonų nerasta</p>
              <button 
                onClick={handleAddTemplate}
                className="mt-4 text-green-600 text-xs font-bold hover:underline"
              >
                Sukurti naują šabloną?
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Dešinysis redagavimo langas */}
      <div className="lg:col-span-8 flex flex-col min-h-0">
        <div className="bg-white border border-gray-200 rounded-xl flex-1 flex flex-col p-6 shadow-sm overflow-hidden relative">

          <div className="flex justify-between items-start mb-6">
            <div className="flex-1">
              <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Šablono pavadinimas</label>
              <input
                type="text"
                className="text-lg font-bold text-gray-900 border-b border-transparent hover:border-gray-200 focus:border-green-500 outline-none bg-transparent w-full"
                value={selectedTemplate.title}
                onChange={e => handleUpdate('title', e.target.value)}
                placeholder="Pvz. Pranešimas tėvams dėl..."
              />
            </div>
            <button 
              onClick={() => handleDelete(selectedTemplate.id)}
              className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition"
              title="Ištrinti šabloną"
            >
              <Trash2 size={20} />
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
            <div>
              <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Kategorija</label>
              <select 
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 font-medium"
                value={selectedTemplate.category}
                onChange={e => handleUpdate('category', e.target.value as TemplateCategory)}
              >
                {categories.filter(c => c !== 'Visi').map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Gavėjo tipas</label>
              <select 
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white text-gray-900 font-medium"
                value={selectedTemplate.recipientType}
                onChange={e => handleUpdate('recipientType', e.target.value as any)}
              >
                <option value="Tėvai">Tėvai</option>
                <option value="Mokytojas">Mokytojas</option>
                <option value="Darbuotojas">Darbuotojas</option>
                <option value="Savivaldybė">Savivaldybė</option>
              </select>
            </div>
          </div>

          <div className="mb-4">
            <label className="text-xs font-bold text-gray-500 uppercase block mb-1">El. laiško tema</label>
            <input
              type="text"
              className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-green-500 outline-none font-medium bg-white text-gray-900"
              value={selectedTemplate.subject}
              onChange={e => handleUpdate('subject', e.target.value)}
              placeholder="Įrašykite temą..."
            />
          </div>

          <div className="flex-1 flex flex-col min-h-0">
            <label className="text-xs font-bold text-gray-500 uppercase block mb-1">Turinys</label>
            <textarea
              className="flex-1 w-full border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-green-500 outline-none font-serif leading-relaxed text-gray-900 bg-white min-h-[200px]"
              value={selectedTemplate.body}
              onChange={e => handleUpdate('body', e.target.value)}
              placeholder="Rašykite laišką čia..."
            />
          </div>

          <div className="mt-6 flex flex-col sm:flex-row gap-3">
             <button 
              onClick={() => alert('Pakeitimai išsaugoti lokaliai.')}
              className="bg-gray-100 text-gray-700 px-6 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-gray-200 transition"
            >
              <Save size={18} />
              <span>Išsaugoti pakeitimus</span>
            </button>
            <div className="flex-1 flex gap-3">
              <button 
                onClick={openInGmail}
                className="flex-1 bg-red-600 text-white px-4 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-red-700 transition shadow-sm"
              >
                <Mail size={18} />
                <span>Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className="flex-1 bg-green-600 text-white px-4 py-3 rounded-lg font-bold flex items-center justify-center space-x-2 hover:bg-green-700 transition shadow-sm"
              >
                <Copy size={18} />
                <span>Kopijuoti</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

