    const children = scenarios.filter(child => child.parent === s.id);

    return (
      <div key={s.id} className="mb-1">
        <button
          onClick={() => {
            setSelectedId(s.id);
            if (hasChildren) toggleParent(s.id);
          }}
          className={`w-full text-left px-3 py-2 rounded-lg transition flex items-center justify-between group ${
            selectedId === s.id ? 'bg-green-600 text-white' : 'hover:bg-gray-100 text-gray-700'
          }`}
        >
          <div className="flex items-center space-x-3 overflow-hidden">
            {hasChildren && (
              <ChevronDown 
                size={14} 
                className={`transition-transform flex-shrink-0 ${isExpanded ? '' : '-rotate-90'}`} 
              />
            )}
            <span className="flex-shrink-0">{s.icon}</span>
            <span className="font-medium text-xs truncate leading-tight">{s.title}</span>
          </div>
          {s.badge && (
            <span className={`text-[10px] font-bold px-1.5 rounded-full ${
              selectedId === s.id ? 'bg-white/20' : 'bg-gray-200 text-gray-600'
            }`}>
              {s.badge}
            </span>
          )}
        </button>

        {hasChildren && isExpanded && (
          <div className="ml-6 mt-1 space-y-1 border-l border-gray-100">
            {children.map(child => (
              <button
                key={child.id}
                onClick={() => setSelectedId(child.id)}
                className={`w-full text-left px-3 py-1.5 rounded-lg transition flex items-center space-x-3 text-xs ${
                  selectedId === child.id ? 'bg-green-50 text-green-700 font-bold' : 'text-gray-500 hover:text-gray-800'
                }`}
              >
                <span className="flex-shrink-0">{child.icon}</span>
                <span className="truncate">{child.title}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    );
  };

  const current = scenarios.find(s => s.id === selectedId) || scenarios[0];

  return (
    <div className="grid grid-cols-1 md:grid-cols-12 gap-6 h-[calc(100vh-180px)]">
      <div className="md:col-span-4 bg-white border border-gray-200 rounded-xl flex flex-col overflow-hidden shadow-sm">
        <div className="p-4 border-b bg-gray-50/50">
          <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest">Situacijų valdymas</h3>
        </div>
        <div className="flex-1 overflow-y-auto p-2 scrollbar-thin">
          {scenarios.map(renderMenuItem)}
        </div>
      </div>

      <div className="md:col-span-8 flex flex-col min-h-0">
        <div className="bg-white border border-gray-200 rounded-xl flex-1 flex flex-col p-6 shadow-sm overflow-y-auto">
          <div className="flex items-center space-x-3 mb-8">
            <div className="p-3 bg-gray-50 rounded-2xl">
              {current.icon}
            </div>
            <div>
              <h3 className="text-2xl font-bold text-gray-900 leading-tight">{current.title}</h3>
              {current.parent && (
                <p className="text-xs text-green-600 font-medium mt-1">
                  Kategorija: {scenarios.find(p => p.id === current.parent)?.title}
                </p>
              )}
            </div>
          </div>

          <div className="space-y-8">
            <section>
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center">
                <Zap size={14} className="mr-2 text-green-500" />
                Veikimo schema
              </h4>
              <div className="space-y-3">
                {current.scheme.map((step, idx) => (
                  <div key={idx} className="flex items-start space-x-4">
                    <div className="flex-shrink-0 mt-1">
                      <div className="w-6 h-6 rounded-full flex items-center justify-center font-bold text-green-600 text-xs bg-green-50 border border-green-100">
                        {idx + 1}
                      </div>
                    </div>
                    <div className="bg-white flex-1 p-3 rounded-xl border border-gray-100 text-gray-700 text-sm leading-relaxed font-medium shadow-sm">
                      {step}
                    </div>
                  </div>
                ))}
              </div>
            </section>

            <section className="bg-blue-50/50 border border-blue-100 rounded-2xl p-6 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-5 text-blue-600">
                <Info size={64} />
              </div>
              <h4 className="text-[10px] font-bold text-blue-700 uppercase tracking-widest mb-2 flex items-center">
                <Info size={14} className="mr-2" />
                Svarbi informacija
              </h4>
              <p className="text-sm text-blue-900 leading-relaxed font-medium relative z-10">
                {current.additional}
              </p>
            </section>
          </div>

          <div className="mt-auto pt-8 border-t flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center space-x-2 text-xs text-gray-500">
              <HelpCircle size={16} className="text-gray-400" />
              <span>Reikia pagalbos įgyvendinant schemą?</span>
            </div>
            <button className="bg-green-50 text-green-700 px-4 py-2 rounded-lg font-bold text-xs hover:bg-green-100 transition flex items-center space-x-2">
              <span>Kreiptis į specialistą</span>
              <ChevronRight size={14} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ScenariosTab;

import React, { useState } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, MessageSquare, Edit2, Plus, Trash2, X, Check, AlertCircle, AlertTriangle, ExternalLink } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const initialFormState: Partial<Specialist> = {
    name: '',
    category: SpecialistCategory.SOCIALINIAI,
    classes: '',
    phone: '',
    office: '',
    email: ''
  };

  const [form, setForm] = useState<Partial<Specialist>>(initialFormState);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = (data: Partial<Specialist>) => {
    const newErrors: Record<string, string> = {};
    if (!data.name?.trim()) newErrors.name = 'Vardas yra privalomas';
    if (data.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) {
      newErrors.email = 'Neteisingas el. pašto formatas';
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleEdit = (s: Specialist) => {
    setEditingId(s.id);
    setForm(s);
    setErrors({});
  };

  const handleSave = () => {
    if (!validate(form)) return;
    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...form } as Specialist : s));
      setEditingId(null);
    } else {
      const newSpecialist: Specialist = {
        ...form as Specialist,
        id: Date.now().toString(),
      };
      setSpecialists(prev => [...prev, newSpecialist]);
      setIsAdding(false);
    }
    setForm(initialFormState);
  };

  const initiateDelete = (id: string) => setDeleteConfirmId(id);

  const confirmDelete = () => {
    if (deleteConfirmId) {
      setSpecialists(prev => prev.filter(s => s.id !== deleteConfirmId));
      setDeleteConfirmId(null);
    }
  };

  const categories = Object.values(SpecialistCategory);

  const renderForm = (isNew: boolean = false) => (
    <div className="space-y-3 p-4 bg-gray-50 rounded-xl border border-gray-200">
      <div className="grid grid-cols-1 gap-3">
        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase mb-1 block">Vardas Pavardė</label>
          <input 
            className={`w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white ${errors.name ? 'border-red-500' : 'border-gray-300'}`}
            value={form.name} 
            onChange={e => setForm({...form, name: e.target.value})}
            placeholder="Jonas Jonaitis"
          />
        </div>
        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase mb-1 block">Pareigos / Klasės</label>
          <input 
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white"
            value={form.classes} 
            onChange={e => setForm({...form, classes: e.target.value})}
            placeholder="Pvz. 5-8 klasės"
          />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase mb-1 block">Telefonas</label>
            <input 
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white"
              value={form.phone} 
              onChange={e => setForm({...form, phone: e.target.value})}
              placeholder="+370..."
            />
          </div>
          <div>
            <label className="text-[10px] font-bold text-gray-400 uppercase mb-1 block">Kabinetas</label>
            <input 
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white"
              value={form.office} 
              onChange={e => setForm({...form, office: e.target.value})}
              placeholder="43 kab."
            />
          </div>
        </div>
        <div>
          <label className="text-[10px] font-bold text-gray-400 uppercase mb-1 block">El. paštas</label>
          <input 
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-green-500 outline-none bg-white"
            value={form.email} 
            onChange={e => setForm({...form, email: e.target.value})}
            placeholder="vardas.pavarde@antakalnio.lt"
          />
        </div>
      </div>
      <div className="flex space-x-2 pt-2">
        <button onClick={handleSave} className="flex-1 bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-bold flex items-center justify-center space-x-2 hover:bg-green-700 transition">
          <Check size={16} /> <span>Išsaugoti</span>
        </button>
        <button onClick={() => {setEditingId(null); setIsAdding(false);}} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg text-sm font-bold hover:bg-gray-300 transition">
          <X size={16} />
        </button>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 pb-10">
      {deleteConfirmId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl max-w-sm w-full p-6 text-center">
            <div className="w-12 h-12 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto mb-4">
              <Trash2 size={24} />
            </div>
            <h3 className="font-bold text-lg mb-2 text-gray-900">Ištrinti kontaktą?</h3>
            <p className="text-sm text-gray-500 mb-6">Ar tikrai norite pašalinti šį specialistą iš sistemos?</p>
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => setDeleteConfirmId(null)} className="py-2.5 bg-gray-100 font-bold rounded-xl text-sm">Atšaukti</button>
              <button onClick={confirmDelete} className="py-2.5 bg-red-600 text-white font-bold rounded-xl text-sm">Ištrinti</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Pagalbos specialistai</h2>
          <p className="text-sm text-gray-500">Mokyklos komanda pasiruošusi padėti spręsti kylančius sunkumus.</p>
        </div>
        <button 
          onClick={() => { setIsAdding(true); setEditingId(null); setForm(initialFormState); }}
          className="bg-green-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center space-x-2 hover:bg-green-700 transition shadow-sm"
        >
          <Plus size={20} />
          <span>Pridėti specialistą</span>
        </button>
      </div>

      {isAdding && (
        <div className="max-w-md mx-auto bg-white p-6 rounded-2xl border-2 border-green-500 shadow-xl mb-10">
          <h3 className="font-bold mb-4 flex items-center text-green-700">
            <Plus size={18} className="mr-2" /> Naujas specialistas
          </h3>
          {renderForm(true)}
        </div>
      )}

      <div className="space-y-12">
        {categories.map(category => {
          const filtered = specialists.filter(s => s.category === category);
          if (filtered.length === 0) return null;

          return (
            <div key={category} className="space-y-4">
              <h3 className="text-[11px] font-bold uppercase tracking-[0.2em] text-green-700 bg-green-50 w-fit px-4 py-1.5 rounded-full border border-green-100">
                {category}
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                {filtered.map(s => (
                  <div key={s.id} className="bg-white p-5 rounded-2xl border border-gray-200 hover:border-green-300 hover:shadow-lg transition-all group relative">
                    {editingId === s.id ? renderForm() : (
                      <>
                        <div className="flex justify-between items-start mb-4">
                          <div className="min-w-0">
                            <h4 className="font-bold text-gray-900 truncate pr-2">{s.name}</h4>
                            <p className="text-[10px] font-bold text-green-600 uppercase mt-0.5 truncate">{s.classes}</p>
                          </div>
                          <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => handleEdit(s)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg"><Edit2 size={14}/></button>
                            <button onClick={() => initiateDelete(s.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={14}/></button>
                          </div>
                        </div>

                        <div className="space-y-2.5 text-sm mb-6">
                          <div className="flex items-center text-gray-600">
                            <Phone size={14} className="mr-3 text-gray-400" />
                            <span className="font-medium">{s.phone}</span>
                          </div>
                          <div className="flex items-center text-gray-600">
                            <Mail size={14} className="mr-3 text-gray-400" />
                            <span className="truncate font-medium">{s.email || '-'}</span>
                          </div>
                          <div className="flex items-center text-gray-600">
                            <div className="text-[10px] font-bold text-gray-400 uppercase w-10">Kab:</div>
                            <span className="font-bold text-gray-800 bg-gray-100 px-2 py-0.5 rounded-md text-xs">{s.office}</span>
                          </div>
                        </div>

                        <div className="grid grid-cols-3 gap-2 pt-4 border-t border-gray-50">
                          <a href={`tel:${s.phone.replace(/\s/g, '')}`} className="flex flex-col items-center p-2 rounded-xl bg-gray-50 hover:bg-green-600 hover:text-white text-green-700 transition-all group/btn">
                            <Phone size={18} />
                            <span className="text-[9px] font-bold mt-1 uppercase">Skambinti</span>
                          </a>
                          <a href={`mailto:${s.email}`} className="flex flex-col items-center p-2 rounded-xl bg-gray-50 hover:bg-red-600 hover:text-white text-red-600 transition-all group/btn">
                            <Mail size={18} />
                            <span className="text-[9px] font-bold mt-1 uppercase">Gmail</span>
                          </a>
                          <a href="https://chat.google.com/" target="_blank" rel="noopener noreferrer" className="flex flex-col items-center p-2 rounded-xl bg-gray-50 hover:bg-blue-600 hover:text-white text-blue-600 transition-all group/btn">
                            <MessageSquare size={18} />
                            <span className="text-[9px] font-bold mt-1 uppercase">Chat</span>
                          </a>
                        </div>
                      </>
                    )}
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

