import React, { useState } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, MessageSquare, Edit2, Plus, Trash2, X, Check } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);

  const initialFormState: Partial<Specialist> = {
    name: '',
    category: SpecialistCategory.SOCIALINIAI,
    classes: '',
    phone: '',
    office: '',
    email: ''
  };

  const [form, setForm] = useState<Partial<Specialist>>(initialFormState);

  const handleSave = () => {
    if (!form.name) return;
    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...form } as Specialist : s));
      setEditingId(null);
    } else {
      const newSpecialist: Specialist = {
        ...form as Specialist,
        id: Date.now().toString(),
      };
      setSpecialists(prev => [...prev, newSpecialist]);
      setIsAdding(false);
    }
    setForm(initialFormState);
  };

  const handleDelete = (id: string) => {
    if (window.confirm('Ištrinti šį kontaktą?')) {
      setSpecialists(prev => prev.filter(s => s.id !== id));
    }
  };

  const categories = Object.values(SpecialistCategory);

  return (
    <div className="space-y-12 pb-20">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Kontaktai</h2>
          <p className="text-sm text-gray-500">Mokyklos pagalbos komanda ir administracija.</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-green-600 text-white px-4 py-2 rounded-lg font-bold flex items-center space-x-2 hover:bg-green-700 transition"
        >
          <Plus size={18} />
          <span>Pridėti</span>
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl border-2 border-green-500 shadow-xl max-w-lg mx-auto">
          <h3 className="font-bold mb-4">Naujas specialistas</h3>
          <div className="space-y-4">
            <input className="w-full border p-2 rounded" placeholder="Vardas Pavardė" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
            <input className="w-full border p-2 rounded" placeholder="Pareigos (didžiosiomis)" value={form.classes} onChange={e => setForm({...form, classes: e.target.value.toUpperCase()})} />
            <input className="w-full border p-2 rounded" placeholder="Telefonas" value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} />
            <input className="w-full border p-2 rounded" placeholder="El. paštas" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
            <input className="w-full border p-2 rounded" placeholder="Kabineto nr." value={form.office} onChange={e => setForm({...form, office: e.target.value})} />
            <select className="w-full border p-2 rounded" value={form.category} onChange={e => setForm({...form, category: e.target.value as SpecialistCategory})}>
              {categories.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <div className="flex space-x-2">
              <button onClick={handleSave} className="flex-1 bg-green-600 text-white p-2 rounded font-bold">Išsaugoti</button>
              <button onClick={() => setIsAdding(false)} className="flex-1 bg-gray-200 p-2 rounded font-bold">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      {categories.map(category => {
        const filtered = specialists.filter(s => s.category === category);
        if (filtered.length === 0) return null;

        return (
          <div key={category} className="space-y-6">
            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest border-b pb-2">{category}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-8">
              {filtered.map(s => (
                <div key={s.id} className="bg-white border border-gray-100 rounded-[24px] shadow-sm flex flex-col overflow-hidden hover:shadow-md transition-shadow group relative">

                  {/* Edit/Delete overlays */}
                  <div className="absolute top-4 right-4 flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => {setEditingId(s.id); setForm(s); setIsAdding(false);}} className="p-1.5 bg-gray-50 rounded-full text-blue-600 hover:bg-blue-50"><Edit2 size={14}/></button>
                    <button onClick={() => handleDelete(s.id)} className="p-1.5 bg-gray-50 rounded-full text-red-600 hover:bg-red-50"><Trash2 size={14}/></button>
                  </div>

                  <div className="p-8 pb-6 flex-1">
                    <h4 className="text-[22px] font-bold text-[#1a1c23] mb-1">{s.name}</h4>
                    <p className="text-[11px] font-bold text-green-600 uppercase tracking-wider mb-6 leading-tight">
                      {s.classes}
                    </p>

                    <div className="space-y-4 mb-6">
                      <div className="flex items-center text-[#5f6368]">
                        <Phone size={18} className="mr-4 text-gray-400 stroke-[1.5]" />
                        <span className="text-[15px] font-medium tracking-tight">{s.phone}</span>
                      </div>
                      <div className="flex items-center text-[#5f6368]">
                        <Mail size={18} className="mr-4 text-gray-400 stroke-[1.5]" />
                        <span className="text-[15px] font-medium tracking-tight truncate">{s.email}</span>
                      </div>
                    </div>

                    <div className="flex items-center">
                      <span className="text-[10px] font-black text-gray-400 uppercase tracking-widest mr-3">KAB:</span>
                      <div className="bg-[#f8f9fa] px-4 py-1.5 rounded-lg border border-gray-50">
                        <span className="text-[13px] font-bold text-gray-800">{s.office}</span>
                      </div>
                    </div>
                  </div>

                  {/* Action Buttons Footer */}
                  <div className="p-4 pt-0">
                    <div className="grid grid-cols-3 gap-3">
                      <a href={`tel:${s.phone.replace(/\s/g, '')}`} className="flex flex-col items-center justify-center py-4 rounded-2xl bg-[#f8f9fa] hover:bg-green-50 transition-colors group/btn">
                        <Phone size={22} className="text-green-600 mb-1" />
                        <span className="text-[9px] font-black text-green-700 uppercase tracking-tighter">SKAMBINTI</span>
                      </a>
                      <a href={`mailto:${s.email}`} className="flex flex-col items-center justify-center py-4 rounded-2xl bg-[#f8f9fa] hover:bg-red-50 transition-colors group/btn">
                        <Mail size={22} className="text-red-600 mb-1" />
                        <span className="text-[9px] font-black text-red-700 uppercase tracking-tighter">GMAIL</span>
                      </a>
                      <a href="https://chat.google.com/" target="_blank" rel="noopener noreferrer" className="flex flex-col items-center justify-center py-4 rounded-2xl bg-[#f8f9fa] hover:bg-blue-50 transition-colors group/btn">
                        <MessageSquare size={22} className="text-blue-600 mb-1" />
                        <span className="text-[9px] font-black text-blue-700 uppercase tracking-tighter">CHAT</span>
                      </a>
                    </div>
                  </div>

                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default ContactsTab;

