                </div>
              )}
            </div>
          </div>

          <div className="space-y-10">
            <section>
              <h4 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-6 flex items-center">
                <Activity size={14} className="mr-2 text-green-500" />
