              <p className="text-[15px] text-amber-950 leading-relaxed font-bold relative z-10">
                {current.additional}
              </p>
            </section>
          </div>

          <div className="mt-auto pt-10 border-t flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="flex items-center space-x-3 text-xs text-gray-500 font-medium">
              <HelpCircle size={18} className="text-gray-400" />
              <span>Prireikus konsultacijos, kreipkitės į budintį vadovą.</span>
            </div>
            <button className="bg-green-600 text-white px-6 py-2.5 rounded-xl font-bold text-sm hover:bg-green-700 transition-all flex items-center space-x-2 shadow-lg shadow-green-100">
              <span>Kreiptis pagalbos</span>
              <ChevronRight size={16} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

