export enum SpecialistCategory {
  SOCIALINIAI = 'Socialiniai pedagogai',
  SPECIALIEJI = 'Specialieji pedagogai',
  LOGOPEDAI = 'Logopedai',
  PSICHOLOGAI = 'Psichologai',
  ADMINISTRACIJA = 'Mokyklos vadovai',
  SVEIKATA = 'Sveikatos priežiūra',
}

export interface Specialist {
  id: string;
  name: string;
  category: SpecialistCategory;
  classes: string;
  phone: string;
  office: string;
  email?: string;
}

export type TemplateCategory = 
  | 'Incidentai / krizės'
  | 'Sveikata'
  | 'Administraciniai'
  | 'Lankomumas' 
  | 'Telefonai' 
  | 'Patyčios' 
  | 'Uniformos' 
  | 'Mokymasis / SUP' 
  | 'Aplinka';

export interface EmailTemplate {
  id: string;
  title: string;
  category: TemplateCategory;
  recipientType: 'Tėvai' | 'Mokytojas' | 'Savivaldybė' | 'Darbuotojas' | 'Pedagogai';
  subject: string;
  body: string;
  to?: string;
  cc?: string;
}

import React, { useState, useMemo } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, Trash2, Save, X, AlertCircle, Info } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [templates, setTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');

  const selectedTemplate = useMemo(() => 
    templates.find(t => t.id === selectedId) || templates[0], 
    [templates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleDelete = (id: string) => {
    if (templates.length <= 1) return;
    if (window.confirm('Ar tikrai norite ištrinti šį šabloną?')) {
      const newTemplates = templates.filter(t => t.id !== id);
      setTemplates(newTemplates);
      setSelectedId(newTemplates[0].id);
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };
    setTemplates(prev => [newTemplate, ...prev]);
    setSelectedId(newId);
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Incidentai / krizės', 'Sveikata', 'Administraciniai', 'Lankomumas', 
    'Telefonai', 'Patyčios', 'Uniformos', 'Mokymasis / SUP', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return templates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase()) ||
                           t.body.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [templates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    alert('Tekstas nukopijuotas! Galite įklijuoti į Mano Dienynas pranešimų langą.');
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="flex flex-col space-y-6 h-[calc(100vh-160px)]">
      {/* ABC Instruction Header */}
      <div className="bg-blue-50 border border-blue-100 p-5 rounded-3xl flex items-start space-x-4 shadow-sm">
        <div className="bg-blue-600 p-2 rounded-xl text-white flex-shrink-0">
          <Info size={20} />
        </div>
        <div>
          <h4 className="font-black text-blue-900 uppercase text-xs tracking-widest mb-1">⁉️ ABC: Kaip naudotis šablonais?</h4>
          <p className="text-sm text-blue-800 leading-relaxed font-medium">
            Paspaudus <span className="font-black">GMAIL</span> mygtuką, laiškas suformuojamas automatiškai. 
            Jeigu siunčiate per dienyną – spauskite <span className="font-black">KOPIJUOTI</span> ir įklijuokite tekstą ten.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 min-h-0">
        {/* Left List */}
        <div className="lg:col-span-4 border border-gray-200 rounded-3xl bg-white flex flex-col overflow-hidden shadow-sm">
          <div className="p-4 border-b border-gray-100 space-y-3">
            <div className="flex items-center space-x-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                <input
                  type="text"
                  placeholder="Ieškoti šablonų..."
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm bg-white text-gray-900"
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                />
              </div>
              <button 
                onClick={handleAddTemplate}
                className="p-2 bg-green-600 text-white rounded-xl hover:bg-green-700 transition shadow-sm"
              >
                <Plus size={20} />
              </button>
            </div>
            <div className="flex overflow-x-auto pb-1 space-x-2 scrollbar-hide">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[9px] font-black uppercase border transition-all ${
                    activeCategory === cat 
                      ? 'bg-green-700 text-white border-green-700' 
                      : 'bg-gray-50 text-gray-500 hover:bg-gray-100 border-gray-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1">
            {filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-4 rounded-2xl transition-all flex items-center justify-between group ${
                  selectedId === t.id ? 'bg-green-50 shadow-sm' : 'hover:bg-gray-50'
                }`}
              >
                <div className="min-w-0">
                  <p className="text-[9px] font-black uppercase text-green-700 mb-1 opacity-70">
                    {t.category}
                  </p>
                  <h4 className={`font-bold text-sm truncate ${selectedId === t.id ? 'text-green-900' : 'text-gray-900'}`}>{t.title}</h4>
                </div>
                <ChevronRight size={16} className={`text-gray-300 transition-transform ${selectedId === t.id ? 'text-green-600 translate-x-1' : ''}`} />
              </button>
            ))}
          </div>
        </div>

        {/* Right Editor */}
        <div className="lg:col-span-8 flex flex-col min-h-0">
          <div className="bg-white border border-gray-200 rounded-3xl flex-1 flex flex-col p-8 shadow-sm overflow-hidden relative">
            <div className="flex justify-between items-start mb-8">
              <div className="flex-1">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Pavadinimas</label>
                <input
                  type="text"
                  className="text-2xl font-black text-gray-900 border-b-2 border-transparent hover:border-gray-100 focus:border-green-500 outline-none bg-transparent w-full transition-colors"
                  value={selectedTemplate.title}
                  onChange={e => handleUpdate('title', e.target.value)}
                />
              </div>
              <button onClick={() => handleDelete(selectedTemplate.id)} className="p-2 text-gray-300 hover:text-red-600 transition"><Trash2 size={20}/></button>
            </div>

            <div className="grid grid-cols-2 gap-6 mb-6">
              <div>
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Gavėjas</label>
                <div className="px-4 py-2 bg-gray-50 rounded-xl border border-gray-100 text-sm font-bold text-gray-700">
                  {selectedTemplate.recipientType}
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Tema</label>
                <input
                  type="text"
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm font-bold text-gray-900"
                  value={selectedTemplate.subject}
                  onChange={e => handleUpdate('subject', e.target.value)}
                />
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-0">
              <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest block mb-2">Turinys</label>
              <textarea
                className="flex-1 w-full border border-gray-100 rounded-2xl p-6 focus:ring-2 focus:ring-green-500 outline-none font-medium leading-relaxed text-gray-800 bg-gray-50/30 resize-none text-[15px]"
                value={selectedTemplate.body}
                onChange={e => handleUpdate('body', e.target.value)}
              />
            </div>

            <div className="mt-8 flex gap-4">
              <button 
                onClick={openInGmail}
                className="flex-1 bg-red-600 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-2 hover:bg-red-700 transition shadow-lg shadow-red-100"
              >
                <Mail size={18} />
                <span>Siųsti per Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className="flex-1 bg-green-700 text-white py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center space-x-2 hover:bg-green-800 transition shadow-lg shadow-green-100"
              >
                <Copy size={18} />
                <span>Kopijuoti (Dienynui)</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TemplatesTab;

