import React, { useState, useMemo, useEffect } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, RotateCcw, Info, Trash2 } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  // Local state for editing during the session
  const [sessionTemplates, setSessionTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');

  const selectedTemplate = useMemo(() => 
    sessionTemplates.find(t => t.id === selectedId) || sessionTemplates[0], 
    [sessionTemplates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleReset = () => {
    if (window.confirm('Ar tikrai norite atstatyti visus šio laiško tekstus į pradinius?')) {
      const original = INITIAL_TEMPLATES.find(t => t.id === selectedId);
      if (original) {
        setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...original } : t));
      }
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };
    setSessionTemplates(prev => [newTemplate, ...prev]);
    setSelectedId(newId);
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Incidentai / krizės', 'Sveikata', 'Administraciniai', 'Lankomumas', 
    'Telefonai', 'Patyčios', 'Uniformos', 'Mokymasis / SUP', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return sessionTemplates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [sessionTemplates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    alert('Tekstas nukopijuotas!');
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="flex flex-col space-y-6 h-[calc(100vh-160px)]">
      {/* ABC Header Info */}
      <div className="bg-blue-50 border border-blue-100 p-5 rounded-3xl flex items-start space-x-4 shadow-sm">
        <div className="bg-blue-600 p-2 rounded-xl text-white flex-shrink-0">
          <Info size={20} />
        </div>
        <div>
          <h4 className="font-black text-blue-900 uppercase text-[10px] tracking-widest mb-1">⁉️ ABC: Kaip naudotis šablonais?</h4>
          <p className="text-sm text-blue-800 leading-relaxed">
            Paspaudus <span className="font-bold">GMAIL</span> – laiškas suformuojamas el. pašte. Jei siunčiate per <span className="font-bold">dienyną</span> – tiesiog nukopijuokite tekstą. Redaguokite laisvai – pakeitimai išliks iki kito puslapio perkrovimo.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 min-h-0">
        {/* Left List */}
        <div className="lg:col-span-4 border border-gray-200 rounded-3xl bg-white flex flex-col overflow-hidden shadow-sm">
          <div className="p-4 border-b border-gray-100 space-y-3">
            <div className="flex items-center space-x-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
                <input
                  type="text"
                  placeholder="Ieškoti šablonų..."
                  className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-sm bg-white text-gray-900"
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                />
              </div>
              <button 
                onClick={handleAddTemplate}
                className="p-2 bg-green-600 text-white rounded-xl hover:bg-green-700 transition shadow-sm"
              >
                <Plus size={20} />
              </button>
            </div>
            <div className="flex overflow-x-auto pb-1 space-x-2 scrollbar-hide">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[9px] font-black uppercase border transition-all ${
                    activeCategory === cat 
                      ? 'bg-green-700 text-white border-green-700' 
                      : 'bg-gray-50 text-gray-500 hover:bg-gray-100 border-gray-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
          <div className="flex-1 overflow-y-auto p-2 space-y-1 bg-gray-50/30">
            {filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-3 rounded-2xl transition-all flex items-center justify-between group ${
                  selectedId === t.id ? 'bg-white shadow-md border border-gray-100' : 'hover:bg-white/50'
                }`}
              >
                <div className="min-w-0 flex-1">
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="text-[8px] font-black text-green-700 uppercase tracking-widest bg-green-50 px-1.5 py-0.5 rounded">
                      {t.category.split(' ')[0]}
                    </span>
                    {t.level && (
                      <span className={`text-[8px] font-black text-white uppercase px-1.5 py-0.5 rounded ${
                        t.level === 'A' ? 'bg-blue-500' : t.level === 'B' ? 'bg-orange-500' : 'bg-red-600'
                      }`}>
                        {t.level} LYGIS
                      </span>
                    )}
                  </div>
                  <h4 className={`font-bold text-xs truncate ${selectedId === t.id ? 'text-green-900' : 'text-gray-900'}`}>{t.title}</h4>
                  {t.role && <p className="text-[10px] text-gray-400 font-medium italic">{t.role}</p>}
                </div>
                <ChevronRight size={14} className={`text-gray-300 transition-transform ${selectedId === t.id ? 'text-green-600 translate-x-1' : ''}`} />
              </button>
            ))}
          </div>
        </div>

        {/* Right Editor */}
        <div className="lg:col-span-8 flex flex-col min-h-0 bg-white border border-gray-200 rounded-3xl shadow-sm overflow-hidden">
          <div className="p-8 flex-1 flex flex-col overflow-y-auto scrollbar-thin">
            <div className="flex justify-between items-start mb-8">
              <div className="flex-1">
                <div className="flex items-center space-x-2 mb-2">
                   <label className="text-[9px] font-black text-gray-400 uppercase tracking-[0.2em]">Pavadinimas</label>
                   {selectedTemplate.level && (
                     <span className="text-[8px] font-black bg-gray-100 text-gray-500 px-2 py-0.5 rounded uppercase">Etalonas: {selectedTemplate.level} lygis ({selectedTemplate.role})</span>
                   )}
                </div>
                <input
                  type="text"
                  className="text-2xl font-black text-gray-900 border-b-2 border-transparent hover:border-gray-100 focus:border-green-500 outline-none bg-transparent w-full transition-colors"
                  value={selectedTemplate.title}
                  onChange={e => handleUpdate('title', e.target.value)}
                />
              </div>
              <button 
                onClick={handleReset}
                title="Atstatyti į pradinį tekstą"
                className="p-3 text-gray-300 hover:text-green-600 transition hover:bg-green-50 rounded-2xl"
              >
                <RotateCcw size={20}/>
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
              <div className="space-y-4">
                <div>
                   <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">Gavėjas (Kam)</label>
                   <input
                    type="text"
                    placeholder="to@example.com"
                    className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-xs font-bold text-gray-700"
                    value={selectedTemplate.to || ''}
                    onChange={e => handleUpdate('to', e.target.value)}
                  />
                </div>
                <div>
                   <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">Kopija (Cc)</label>
                   <input
                    type="text"
                    placeholder="cc@example.com"
                    className="w-full px-4 py-2 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-xs font-bold text-gray-700"
                    value={selectedTemplate.cc || ''}
                    onChange={e => handleUpdate('cc', e.target.value)}
                  />
                </div>
              </div>
              <div>
                <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-1">Tema</label>
                <textarea
                  className="w-full px-4 py-3 bg-gray-50 border border-gray-100 rounded-xl focus:ring-2 focus:ring-green-500 outline-none text-xs font-bold text-gray-900 h-[86px] resize-none"
                  value={selectedTemplate.subject}
                  onChange={e => handleUpdate('subject', e.target.value)}
                />
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-[300px]">
              <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest block mb-2">Laiško turinys (redaguojamas)</label>
              <textarea
                className="flex-1 w-full border border-gray-100 rounded-2xl p-6 focus:ring-2 focus:ring-green-500 outline-none font-medium leading-relaxed text-gray-800 bg-gray-50/30 resize-none text-[14px]"
                value={selectedTemplate.body}
                onChange={e => handleUpdate('body', e.target.value)}
              />
            </div>

            <div className="mt-8 flex flex-col sm:flex-row gap-4">
              <button 
                onClick={openInGmail}
                className="flex-1 bg-[#EA4335] text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center space-x-2 hover:bg-[#d93025] transition shadow-lg shadow-red-100"
              >
                <Mail size={16} />
                <span>Siųsti per Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className="flex-1 bg-green-700 text-white py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center space-x-2 hover:bg-green-800 transition shadow-lg shadow-green-100"
              >
                <Copy size={16} />
                <span>Kopijuoti (Dienynui)</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TemplatesTab;

