import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SchemesTab from './components/SchemesTab';
import ContactsTab from './components/ContactsTab';
import TemplatesTab from './components/TemplatesTab';
import ScenariosTab from './components/ScenariosTab';
import IntroTab from './components/IntroTab';
import { Menu, X } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard setActiveTab={setActiveTab} />;
      case 'intro': return <IntroTab setActiveTab={setActiveTab} />;
      case 'schemes': return <SchemesTab />;
      case 'contacts': return <ContactsTab />;
      case 'templates': return <TemplatesTab />;
      case 'scenarios': return <ScenariosTab setActiveTab={setActiveTab} />;
      default: return <Dashboard setActiveTab={setActiveTab} />;
    }
  };

  const getTitle = () => {
    switch (activeTab) {
      case 'dashboard': return 'Sistemos apžvalga';
      case 'intro': return 'Nuostatos ir metodika';
      case 'schemes': return 'Pagalbos procesai';
      case 'contacts': return 'Specialistų kontaktai';
      case 'templates': return 'Komunikacijos šablonai';
      case 'scenarios': return 'Situacijų valdymas';
      default: return 'VAP pagalbos sistema';
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfcfd] flex font-sans antialiased text-slate-900">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-40 md:hidden transition-opacity duration-300" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      {/* Mobile Menu */}
      <div className={`fixed inset-y-0 left-0 w-80 bg-white z-50 transform transition-transform duration-500 ease-[cubic-bezier(0.32,0.72,0,1)] md:hidden shadow-2xl ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 border-b flex justify-between items-center bg-green-800 text-white">
          <div className="flex flex-col">
            <h1 className="text-xl font-black uppercase tracking-tighter">VAP Pagalba</h1>
            <span className="text-[10px] font-bold opacity-60 uppercase tracking-widest mt-1">Saugumo portalas</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={24} /></button>
        </div>
        <nav className="p-6 space-y-2">
          {[
            { id: 'dashboard', label: 'Apžvalga' },
            { id: 'intro', label: 'Nuostatos' },
            { id: 'scenarios', label: 'Situacijos' },
            { id: 'schemes', label: 'Schemos' },
            { id: 'contacts', label: 'Specialistai' },
            { id: 'templates', label: 'Šablonai' }
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveTab(item.id); setIsMobileMenuOpen(false); }}
              className={`w-full text-left px-5 py-4 rounded-2xl flex items-center transition-all duration-200 ${
                activeTab === item.id 
                  ? 'bg-green-50 text-green-800 font-bold shadow-sm' 
                  : 'text-slate-500 font-semibold hover:bg-slate-50'
              }`}
            >
              <span className="text-sm">{item.label}</span>
            </button>
          ))}
        </nav>
      </div>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="bg-white/80 backdrop-blur-xl border-b border-slate-100 h-20 sticky top-0 z-30 px-8 flex items-center justify-between">
          <div className="flex items-center space-x-6">
            <button className="md:hidden p-2.5 -ml-2.5 hover:bg-slate-100 rounded-xl transition-colors" onClick={() => setIsMobileMenuOpen(true)}>
              <Menu size={24} className="text-slate-600" />
            </button>
            <div className="flex flex-col">
              <h2 className="text-lg font-black text-slate-900 uppercase tracking-tighter leading-none">{getTitle()}</h2>
              <div className="flex items-center space-x-2 mt-1.5">
                <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Antakalnio Progimnazija</span>
              </div>
            </div>
          </div>
          <div className="flex items-center space-x-4">
             <div className="hidden sm:flex items-center px-4 py-1.5 bg-slate-50 rounded-full border border-slate-100">
               <span className="text-[11px] font-black text-slate-500 uppercase tracking-widest">Portal V2.5</span>
             </div>
          </div>
        </header>

        <div className="p-8 flex-1 overflow-y-auto w-full">
          <div className="max-w-7xl mx-auto space-y-8">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

