        <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-2xl max-w-2xl mx-auto mb-16 relative">
          <button onClick={() => setIsAdding(false)} className="absolute top-6 right-6 p-2 hover:bg-slate-100 rounded-full text-slate-400 transition-colors"><X size={24}/></button>
          <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mb-8">Specialisto Duomenys</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vardas Pavardė</label>
              <input className="w-full bg-slate-50 border border-slate-100 p-4 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 transition-all font-bold" placeholder="Pvz. Jonas Jonaitis" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
            </div>
