import React, { useState, useMemo, useEffect } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, RotateCcw, Info, Trash2, Edit3, Send, Check } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [sessionTemplates, setSessionTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');
  const [copied, setCopied] = useState(false);

  const selectedTemplate = useMemo(() => 
    sessionTemplates.find(t => t.id === selectedId) || sessionTemplates[0], 
    [sessionTemplates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleReset = () => {
    if (window.confirm('Ar tikrai norite atstatyti visus šio laiško tekstus į pradinius?')) {
      const original = INITIAL_TEMPLATES.find(t => t.id === selectedId);
      if (original) {
        setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...original } : t));
      }
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };
    setSessionTemplates(prev => [newTemplate, ...prev]);
    setSelectedId(newId);
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Incidentai / krizės', 'Sveikata', 'Administraciniai', 'Lankomumas', 
    'Telefonai', 'Patyčios', 'Uniformos', 'Mokymasis / SUP', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return sessionTemplates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [sessionTemplates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="flex flex-col space-y-8 h-[calc(100vh-200px)] animate-in fade-in duration-500">
      {/* Help Banner */}
      <div className="bg-slate-900 text-white p-8 rounded-[40px] flex items-center justify-between shadow-2xl shadow-slate-200">
        <div className="flex items-center space-x-6">
          <div className="bg-green-500/20 p-4 rounded-2xl text-green-400">
            <Info size={32} />
          </div>
          <div>
            <h4 className="font-black uppercase text-xs tracking-[0.2em] mb-1 text-green-400">Pagalba / Instrukcija</h4>
            <p className="text-slate-300 font-medium max-w-xl">
              Pasirinkite šabloną kairėje, redaguokite tekstą dešinėje. Mygtukas <span className="text-white font-bold">GMAIL</span> atidarys pašto programą, o <span className="text-white font-bold">Kopijuoti</span> leis įklijuoti tekstą į Mano Dienyną.
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 flex-1 min-h-0">
        {/* Left List: Templates Navigator */}
        <div className="lg:col-span-4 border border-slate-100 rounded-[36px] bg-white flex flex-col overflow-hidden shadow-sm">
          <div className="p-6 border-b border-slate-50 space-y-4">
            <div className="flex items-center space-x-3">
              <div className="relative flex-1">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  placeholder="Ieškoti laiško..."
                  className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-50 rounded-[20px] focus:bg-white focus:ring-2 focus:ring-green-500/20 focus:border-green-500 outline-none text-sm font-bold transition-all text-slate-900"
                  value={search}
                  onChange={e => setSearch(e.target.value)}
                />
              </div>
              <button 
                onClick={handleAddTemplate}
                className="p-3.5 bg-slate-900 text-white rounded-[20px] hover:bg-slate-800 transition shadow-xl shadow-slate-200"
              >
                <Plus size={20} />
              </button>
            </div>
            <div className="flex overflow-x-auto pb-2 space-x-2 scrollbar-hide">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`flex-shrink-0 px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${
                    activeCategory === cat 
                      ? 'bg-green-700 text-white border-green-700 shadow-lg shadow-green-100' 
                      : 'bg-slate-50 text-slate-500 hover:bg-slate-100 border-slate-50'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-2 bg-slate-50/20 scrollbar-thin">
            {filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-4 rounded-[24px] transition-all flex items-center justify-between group ${
                  selectedId === t.id 
                    ? 'bg-white shadow-xl shadow-slate-200 border border-slate-100 scale-[1.02]' 
                    : 'hover:bg-white/70'
                }`}
              >
                <div className="min-w-0 flex-1">
                  <div className="flex items-center space-x-2 mb-2">
                    {t.level && (
                      <span className={`text-[8px] font-black text-white uppercase px-2 py-0.5 rounded-md ${
                        t.level === 'A' ? 'bg-blue-500' : t.level === 'B' ? 'bg-orange-500' : 'bg-red-600'
                      }`}>
                        {t.level} LYGIS
                      </span>
                    )}
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest truncate max-w-[120px]">
                      {t.category}
                    </span>
                  </div>
                  <h4 className={`font-bold text-[13px] tracking-tight leading-tight ${selectedId === t.id ? 'text-slate-900' : 'text-slate-700 group-hover:text-slate-900'}`}>{t.title}</h4>
                </div>
                <ChevronRight size={16} className={`text-slate-200 transition-all ${selectedId === t.id ? 'text-green-600 translate-x-1' : ''}`} />
              </button>
            ))}
          </div>
        </div>

        {/* Right Editor: Content Area */}
        <div className="lg:col-span-8 flex flex-col min-h-0 bg-white border border-slate-100 rounded-[36px] shadow-sm overflow-hidden">
          <div className="p-10 flex-1 flex flex-col overflow-y-auto scrollbar-thin">
            <div className="flex justify-between items-start mb-10">
              <div className="flex-1">
                <div className="flex items-center space-x-3 mb-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Pavadinimas</label>
                   {selectedTemplate.level && (
                     <div className="h-1 w-1 bg-slate-200 rounded-full"></div>
                   )}
                   {selectedTemplate.level && (
                     <span className="text-[9px] font-black bg-slate-50 text-slate-500 px-3 py-1 rounded-full uppercase tracking-widest">
                       Rekomenduojamas vaidmuo: {selectedTemplate.role}
                     </span>
                   )}
                </div>
                <input
                  type="text"
                  className="text-3xl font-black text-slate-900 border-none outline-none bg-transparent w-full transition-colors tracking-tighter uppercase focus:text-green-700"
                  value={selectedTemplate.title}
                  onChange={e => handleUpdate('title', e.target.value)}
                />
              </div>
              <div className="flex items-center space-x-2">
                <button 
                  onClick={handleReset}
                  title="Atstatyti"
                  className="p-4 text-slate-300 hover:text-amber-600 transition-all hover:bg-amber-50 rounded-[20px]"
                >
                  <RotateCcw size={22}/>
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <div className="space-y-6">
                <div>
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Adresatas (Kam)</label>
                   <input
                    type="text"
                    placeholder="vardas.pavarde@vilnius.lt"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-50 rounded-[20px] focus:bg-white focus:ring-2 focus:ring-green-500/20 focus:border-green-500 outline-none text-sm font-bold text-slate-900 transition-all"
                    value={selectedTemplate.to || ''}
                    onChange={e => handleUpdate('to', e.target.value)}
                  />
                </div>
                <div>
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Kopija (Cc)</label>
                   <input
                    type="text"
                    placeholder="direktorius@antakalnio.lt"
                    className="w-full px-5 py-4 bg-slate-50 border border-slate-50 rounded-[20px] focus:bg-white focus:ring-2 focus:ring-green-500/20 focus:border-green-500 outline-none text-sm font-bold text-slate-900 transition-all"
                    value={selectedTemplate.cc || ''}
                    onChange={e => handleUpdate('cc', e.target.value)}
                  />
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2 ml-1">Laiško Tema</label>
                <textarea
                  className="w-full px-5 py-4 bg-slate-50 border border-slate-50 rounded-[20px] focus:bg-white focus:ring-2 focus:ring-green-500/20 focus:border-green-500 outline-none text-sm font-black text-slate-900 h-[132px] resize-none transition-all uppercase leading-tight"
                  value={selectedTemplate.subject}
                  onChange={e => handleUpdate('subject', e.target.value)}
                />
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-[400px]">
              <div className="flex items-center justify-between mb-3 px-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Laiško turinio redaktorius</label>
                <div className="flex items-center space-x-2 text-[10px] font-bold text-green-600 uppercase tracking-widest">
                  <Edit3 size={12} />
                  <span>Pakeitimai išsaugomi laikinai</span>
                </div>
              </div>
              <textarea
                className="flex-1 w-full border border-slate-50 rounded-[32px] p-8 focus:ring-2 focus:ring-green-500/20 focus:border-green-500 outline-none font-medium leading-relaxed text-slate-700 bg-slate-50/30 resize-none text-[16px] shadow-inner transition-all"
                value={selectedTemplate.body}
                onChange={e => handleUpdate('body', e.target.value)}
              />
            </div>

            <div className="mt-10 flex flex-col sm:flex-row gap-5">
              <button 
                onClick={openInGmail}
                className="group flex-1 bg-slate-900 text-white py-5 rounded-[24px] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-3 hover:bg-slate-800 transition-all shadow-2xl shadow-slate-200"
              >
                <Send size={18} className="group-hover:translate-x-1 transition-transform" />
                <span>Siųsti per Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className={`flex-1 py-5 rounded-[24px] font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center space-x-3 transition-all ${
                  copied 
                    ? 'bg-green-100 text-green-800' 
                    : 'bg-green-700 text-white hover:bg-green-800 shadow-2xl shadow-green-100'
                }`}
              >
                {copied ? <Check size={18} /> : <Copy size={18} />}
                <span>{copied ? 'Nukopijuota!' : 'Kopijuoti Turinį'}</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

