import React, { useState, useMemo } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, MessageSquare, Edit2, Plus, Trash2, X, Check, MapPin, Hash, AlertCircle, Search, UserX, AlertTriangle } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [searchTerm, setSearchTerm] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const initialFormState: Partial<Specialist> = {
    name: '',
    category: SpecialistCategory.SOCIALINIAI,
    classes: '',
    phone: '',
    office: '',
    email: ''
  };

  const [form, setForm] = useState<Partial<Specialist>>(initialFormState);

  const validate = () => {
    const newErrors: { [key: string]: string } = {};

    if (!form.name || form.name.trim().length < 3) {
      newErrors.name = 'Vardas per trumpas';
    }

    if (!form.classes || form.classes.trim().length < 2) {
      newErrors.classes = 'Nurodykite pareigas';
    }

    const phoneClean = (form.phone || '').replace(/\s+/g, '');
    const phoneRegex = /^(\+370|8)\d{8}$/;
    if (form.phone && !phoneRegex.test(phoneClean)) {
      newErrors.phone = 'Neteisingas formatas (pvz. +37060000000)';
    } else if (!form.phone) {
      newErrors.phone = 'Telefonas privalomas';
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (form.email && !emailRegex.test(form.email)) {
      newErrors.email = 'Neteisingas el. pašto formatas';
    } else if (!form.email) {
      newErrors.email = 'El. paštas privalomas';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = () => {
    if (!validate()) return;

    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...form } as Specialist : s));
      setEditingId(null);
    } else {
      const newSpecialist: Specialist = {
        ...form as Specialist,
        id: Date.now().toString(),
      };
      setSpecialists(prev => [...prev, newSpecialist]);
      setIsAdding(false);
    }
    setForm(initialFormState);
    setErrors({});
  };

  const handleCancel = () => {
    setIsAdding(false);
    setEditingId(null);
    setForm(initialFormState);
    setErrors({});
  };

