    if (deleteConfirmId) {
      setSpecialists(prev => prev.filter(s => s.id !== deleteConfirmId));
      setDeleteConfirmId(null);
    }
  };

  const categories = Object.values(SpecialistCategory);

  const filteredSpecialists = useMemo(() => {
    if (!searchTerm.trim()) return specialists;
    const lowerSearch = searchTerm.toLowerCase();
    return specialists.filter(s => 
      s.name.toLowerCase().includes(lowerSearch) || 
      s.classes.toLowerCase().includes(lowerSearch) ||
      s.category.toLowerCase().includes(lowerSearch) ||
      (s.office && s.office.toLowerCase().includes(lowerSearch))
    );
