import React, { useState, useMemo } from 'react';
import { EmailTemplate, TemplateCategory } from '../types';
import { INITIAL_TEMPLATES } from '../constants';
import { Search, Copy, ChevronRight, Mail, Plus, RotateCcw, Info, Edit3, Send, Check } from 'lucide-react';

const TemplatesTab: React.FC = () => {
  const [sessionTemplates, setSessionTemplates] = useState<EmailTemplate[]>(INITIAL_TEMPLATES);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TEMPLATES[0].id);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<TemplateCategory | 'Visi'>('Visi');
  const [copied, setCopied] = useState(false);

  const selectedTemplate = useMemo(() => 
    sessionTemplates.find(t => t.id === selectedId) || sessionTemplates[0], 
    [sessionTemplates, selectedId]
  );

  const handleUpdate = (field: keyof EmailTemplate, value: string) => {
    setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...t, [field]: value } : t));
  };

  const handleReset = () => {
    if (window.confirm('Ar tikrai norite atstatyti šį šabloną į pradinį?')) {
      const original = INITIAL_TEMPLATES.find(t => t.id === selectedId);
      if (original) {
        setSessionTemplates(prev => prev.map(t => t.id === selectedId ? { ...original } : t));
      }
    }
  };

  const handleAddTemplate = () => {
    const newId = `custom-${Date.now()}`;
    const newTemplate: EmailTemplate = {
      id: newId,
      title: 'Naujas šablonas',
      category: activeCategory === 'Visi' ? 'Administraciniai' : activeCategory,
      recipientType: 'Tėvai',
      subject: 'Nauja tema',
      body: 'Sveiki,\n\n[Jūsų tekstas čia]',
    };
    setSessionTemplates(prev => [newTemplate, ...prev]);
    setSelectedId(newId);
  };

  const categories: (TemplateCategory | 'Visi')[] = [
    'Visi', 'Incidentai / krizės', 'Sveikata', 'Administraciniai', 'Lankomumas', 
    'Telefonai', 'Patyčios', 'Uniformos', 'Mokymasis / SUP', 'Aplinka'
  ];

  const filteredTemplates = useMemo(() => {
    return sessionTemplates.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(search.toLowerCase()) || 
                           t.subject.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = activeCategory === 'Visi' || t.category === activeCategory;
      return matchesSearch && matchesCategory;
    });
  }, [sessionTemplates, search, activeCategory]);

  const copyToClipboard = () => {
    const text = `Tema: ${selectedTemplate.subject}\n\n${selectedTemplate.body}`;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const openInGmail = () => {
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const mailto = `mailto:${to}?cc=${cc}&subject=${encodeURIComponent(selectedTemplate.subject)}&body=${encodeURIComponent(selectedTemplate.body)}`;
    window.location.href = mailto;
  };

  return (
    <div className="flex flex-col space-y-8 h-[calc(100vh-140px)] animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 flex-1 min-h-0">
        {/* Navigation Panel */}
        <div className="lg:col-span-4 flex flex-col bg-white border border-slate-200 rounded-[2rem] overflow-hidden shadow-sm">
          <div className="p-6 border-b border-slate-100 space-y-5">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-bold text-slate-900 uppercase tracking-wider">Laiškų šablonai</h3>
              <button 
                onClick={handleAddTemplate}
                className="p-2.5 bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition shadow-lg shadow-emerald-600/10"
              >
                <Plus size={18} />
              </button>
            </div>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input
                type="text"
                placeholder="Ieškoti..."
                className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none text-sm transition-all"
                value={search}
                onChange={e => setSearch(e.target.value)}
              />
            </div>
            <div className="flex overflow-x-auto pb-1 space-x-2 scrollbar-hide">
              {categories.map(cat => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className={`flex-shrink-0 px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest border transition-all ${
                    activeCategory === cat 
                      ? 'bg-slate-900 text-white border-slate-900 shadow-md' 
                      : 'bg-white text-slate-500 hover:bg-slate-50 border-slate-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-2 bg-slate-50/30">
            {filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => setSelectedId(t.id)}
                className={`w-full text-left p-4 rounded-2xl transition-all flex items-center justify-between group ${
                  selectedId === t.id 
                    ? 'bg-white shadow-md border border-slate-200 ring-2 ring-emerald-500/5' 
                    : 'hover:bg-white/80'
                }`}
              >
                <div className="min-w-0 flex-1">
                  <div className="flex items-center space-x-2 mb-1.5">
                    {t.level && (
                      <span className={`text-[8px] font-black text-white px-1.5 py-0.5 rounded ${
                        t.level === 'A' ? 'bg-blue-500' : t.level === 'B' ? 'bg-orange-500' : 'bg-red-600'
                      }`}>
                        {t.level}
                      </span>
                    )}
                    <span className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter truncate">
                      {t.category}
                    </span>
                  </div>
                  <h4 className={`font-bold text-[13px] truncate ${selectedId === t.id ? 'text-slate-900' : 'text-slate-600 group-hover:text-slate-900'}`}>{t.title}</h4>
                </div>
                <ChevronRight size={14} className={`text-slate-300 transition-all ${selectedId === t.id ? 'text-emerald-600 translate-x-1' : ''}`} />
              </button>
            ))}
          </div>
        </div>

        {/* Editor Panel */}
        <div className="lg:col-span-8 flex flex-col bg-white border border-slate-200 rounded-[2rem] shadow-sm overflow-hidden">
          <div className="p-8 md:p-10 flex-1 flex flex-col overflow-y-auto">
            <div className="flex justify-between items-start mb-10">
              <div className="flex-1">
                <div className="flex items-center space-x-3 mb-2">
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Pavadinimas</label>
                   {selectedTemplate.role && (
                     <span className="text-[9px] font-bold bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded-full uppercase tracking-widest">
                       {selectedTemplate.role}
                     </span>
                   )}
                </div>
                <input
                  type="text"
                  className="text-2xl md:text-3xl font-extrabold text-slate-900 border-none outline-none bg-transparent w-full tracking-tight focus:text-emerald-700 transition-colors"
                  value={selectedTemplate.title}
                  onChange={e => handleUpdate('title', e.target.value)}
                />
              </div>
              <button 
                onClick={handleReset}
                title="Atstatyti"
                className="p-3 text-slate-300 hover:text-amber-600 transition-all hover:bg-amber-50 rounded-xl"
              >
                <RotateCcw size={20}/>
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div className="space-y-4">
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2 ml-1">Kam</label>
                   <input
                    type="text"
                    placeholder="Adresatas"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none text-sm font-semibold transition-all"
                    value={selectedTemplate.to || ''}
                    onChange={e => handleUpdate('to', e.target.value)}
                  />
                </div>
                <div>
                   <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2 ml-1">Kopija (Cc)</label>
                   <input
                    type="text"
                    placeholder="Kopija"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none text-sm font-semibold transition-all"
                    value={selectedTemplate.cc || ''}
                    onChange={e => handleUpdate('cc', e.target.value)}
                  />
                </div>
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block mb-2 ml-1">Tema</label>
                <textarea
                  className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none text-sm font-bold text-slate-900 h-[126px] resize-none transition-all leading-snug"
                  value={selectedTemplate.subject}
                  onChange={e => handleUpdate('subject', e.target.value)}
                />
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-[350px]">
              <div className="flex items-center justify-between mb-3 px-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest block">Turinys</label>
                <div className="flex items-center space-x-2 text-[10px] font-bold text-emerald-600 uppercase tracking-widest">
                  <Edit3 size={12} />
                  <span>Autosave</span>
                </div>
              </div>
              <textarea
                className="flex-1 w-full border border-slate-100 rounded-[2rem] p-8 focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none font-medium leading-relaxed text-slate-700 bg-slate-50/50 resize-none text-base shadow-inner transition-all"
                value={selectedTemplate.body}
                onChange={e => handleUpdate('body', e.target.value)}
              />
            </div>

            <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button 
                onClick={openInGmail}
                className="group bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm flex items-center justify-center space-x-3 hover:bg-slate-800 transition-all shadow-xl shadow-slate-900/10"
              >
                <Send size={18} className="group-hover:translate-x-1 transition-transform" />
                <span>Siųsti per Gmail</span>
              </button>
              <button 
                onClick={copyToClipboard}
                className={`py-4 rounded-2xl font-bold text-sm flex items-center justify-center space-x-3 transition-all ${
                  copied 
                    ? 'bg-emerald-100 text-emerald-800' 
                    : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-xl shadow-emerald-600/10'
                }`}
              >
                {copied ? <Check size={18} /> : <Copy size={18} />}
                <span>{copied ? 'Nukopijuota!' : 'Kopijuoti'}</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

