import React, { useState, useMemo } from 'react';
import { Specialist, SpecialistCategory } from '../types';
import { INITIAL_SPECIALISTS } from '../constants';
import { Phone, Mail, Edit2, Plus, Trash2, X, MapPin, Search, AlertTriangle, MessageSquareText } from 'lucide-react';

const ContactsTab: React.FC = () => {
  const [specialists, setSpecialists] = useState<Specialist[]>(INITIAL_SPECIALISTS);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [errors, setErrors] = useState<{ [key: string]: string }>({});
  const [searchTerm, setSearchTerm] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const initialFormState: Partial<Specialist> = {
    name: '',
    category: SpecialistCategory.SOCIALINIAI,
    classes: '',
    phone: '',
    office: '',
    email: ''
  };

  const [form, setForm] = useState<Partial<Specialist>>(initialFormState);

  const validate = () => {
    const newErrors: { [key: string]: string } = {};
    if (!form.name || form.name.trim().length < 3) newErrors.name = 'Privalomas';
    if (!form.classes) newErrors.classes = 'Privaloma';
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (form.email && !emailRegex.test(form.email)) newErrors.email = 'Neteisingas el. paštas';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = () => {
    if (!validate()) return;
    if (editingId) {
      setSpecialists(prev => prev.map(s => s.id === editingId ? { ...s, ...form } as Specialist : s));
      setEditingId(null);
    } else {
      setSpecialists(prev => [...prev, { ...form, id: Date.now().toString() } as Specialist]);
      setIsAdding(false);
    }
    setForm(initialFormState);
    setErrors({});
  };

  const categories = Object.values(SpecialistCategory);

  const filteredSpecialists = useMemo(() => {
    if (!searchTerm.trim()) return specialists;
    const s = searchTerm.toLowerCase();
    return specialists.filter(x => x.name.toLowerCase().includes(s) || x.classes.toLowerCase().includes(s));
  }, [specialists, searchTerm]);

  return (
    <div className="space-y-10 pb-16 animate-in fade-in duration-500">
      {/* Delete Dialog */}
      {deleteConfirmId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/10 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl max-sm w-full p-8 text-center border border-slate-200">
            <div className="w-12 h-12 bg-red-50 text-red-600 rounded-xl flex items-center justify-center mx-auto mb-4"><AlertTriangle size={24} /></div>
            <h3 className="text-lg font-bold text-slate-900 mb-2">Ištrinti kontaktą?</h3>
            <p className="text-sm text-slate-500 mb-8">Ar tikrai norite pašalinti šį specialistą iš sąrašo?</p>
            <div className="flex space-x-3">
              <button onClick={() => { setSpecialists(p => p.filter(x => x.id !== deleteConfirmId)); setDeleteConfirmId(null); }} className="flex-1 bg-red-600 text-white py-2.5 rounded-xl text-sm font-bold shadow-sm">Ištrinti</button>
              <button onClick={() => setDeleteConfirmId(null)} className="flex-1 bg-slate-100 text-slate-600 py-2.5 rounded-xl text-sm font-bold">Atšaukti</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-900 tracking-tight">Mokyklos specialistai</h2>
          <p className="text-sm text-slate-500 mt-1">Ugdymo pagalbos komanda ir mokyklos vadovai.</p>
        </div>
        <div className="flex items-center space-x-3 w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input
              type="text"
              placeholder="Ieškoti..."
              className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500/10 focus:border-emerald-500 shadow-sm text-sm"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsAdding(true)}
            className="bg-emerald-700 text-white px-5 py-2.5 rounded-xl font-bold text-sm flex items-center shadow-md hover:bg-emerald-800 transition-colors"
          >
            <Plus size={18} className="mr-2" />
            Naujas
          </button>
        </div>
      </div>

      {(isAdding || editingId) && (
        <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-lg max-w-xl mx-auto relative">
          <button onClick={() => { setIsAdding(false); setEditingId(null); }} className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"><X size={20}/></button>
          <h3 className="text-lg font-bold text-slate-900 mb-6">{editingId ? 'Redaguoti' : 'Pridėti specialistą'}</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider ml-1">Vardas Pavardė</label>
              <input className={`w-full bg-slate-50 border ${errors.name ? 'border-red-300' : 'border-slate-200'} p-3 rounded-xl outline-none text-sm`} value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider ml-1">Pareigos</label>
              <input className={`w-full bg-slate-50 border ${errors.classes ? 'border-red-300' : 'border-slate-200'} p-3 rounded-xl outline-none text-sm`} value={form.classes} onChange={e => setForm({...form, classes: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider ml-1">Kategorija</label>
              <select className="w-full bg-slate-50 border border-slate-200 p-3 rounded-xl outline-none text-sm" value={form.category} onChange={e => setForm({...form, category: e.target.value as SpecialistCategory})}>
                {categories.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div className="space-y-1">
