import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import SchemesTab from './components/SchemesTab';
import ContactsTab from './components/ContactsTab';
import ScenariosTab from './components/ScenariosTab';
import IntroTab from './components/IntroTab';
import TemplatesTab from './components/TemplatesTab';
import { Menu, X, ExternalLink } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedScenarioId, setSelectedScenarioId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
    // Reset scenario selection if navigating to dashboard or other tabs
    if (tab !== 'scenarios') {
      setSelectedScenarioId(null);
    }
  };

  const handleSelectScenario = (id: string) => {
    setSelectedScenarioId(id);
    setActiveTab('scenarios');
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard setActiveTab={handleTabChange} onSelectScenario={handleSelectScenario} />;
      case 'intro': return <IntroTab setActiveTab={handleTabChange} />;
      case 'schemes': return <SchemesTab />;
      case 'contacts': return <ContactsTab />;
      case 'scenarios': return <ScenariosTab setActiveTab={handleTabChange} initialScenarioId={selectedScenarioId} />;
      case 'templates': return <TemplatesTab />;
      default: return <Dashboard setActiveTab={handleTabChange} onSelectScenario={handleSelectScenario} />;
    }
  };

  const getTitle = () => {
    switch (activeTab) {
      case 'dashboard': return 'Apžvalga';
      case 'intro': return 'Metodika';
      case 'schemes': return 'Procesai';
      case 'contacts': return 'Kontaktai';
      case 'scenarios': return 'Situacijos';
      case 'templates': return 'Laiškų šablonai';
      default: return 'VAP Pagalba';
    }
  };

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex font-sans antialiased text-slate-800">
      <Sidebar activeTab={activeTab} setActiveTab={handleTabChange} />

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-40 md:hidden transition-opacity" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <div className={`fixed inset-y-0 left-0 w-72 bg-white z-50 transform transition-transform duration-300 ease-in-out md:hidden shadow-xl ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 border-b flex justify-between items-center bg-emerald-700 text-white">
          <h1 className="text-lg font-bold tracking-tight">VAP PAGALBA</h1>
          <button onClick={() => setIsMobileMenuOpen(false)} className="p-1 hover:bg-white/10 rounded-md"><X size={20} /></button>
        </div>
        <nav className="p-4 space-y-1">
          {[
            { id: 'dashboard', label: 'Apžvalga' },
            { id: 'intro', label: 'Nuostatos' },
            { id: 'scenarios', label: 'Situacijos' },
            { id: 'schemes', label: 'Schemos' },
            { id: 'contacts', label: 'Specialistai' },
            { id: 'templates', label: 'Šablonai' }
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => { handleTabChange(item.id); setIsMobileMenuOpen(false); }}
              className={`w-full text-left px-4 py-3 rounded-xl transition-colors flex items-center justify-between ${
                activeTab === item.id 
                  ? 'bg-emerald-50 text-emerald-700 font-semibold' 
                  : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <span className="text-sm">{item.label}</span>
            </button>
          ))}
        </nav>
      </div>

      <main className="flex-1 flex flex-col min-w-0">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 h-16 sticky top-0 z-30 px-6 md:px-10 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <button className="md:hidden p-2 hover:bg-slate-100 rounded-lg" onClick={() => setIsMobileMenuOpen(true)}>
              <Menu size={22} className="text-slate-600" />
            </button>
            <div>
              <h2 className="text-base font-bold text-slate-900 tracking-tight">{getTitle()}</h2>
              <p className="text-[10px] font-medium text-slate-400 uppercase tracking-widest hidden sm:block">Antakalnio Progimnazija</p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
             <div className="hidden sm:flex items-center px-3 py-1 bg-slate-100 rounded-full">
               <span className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">SISTEMA AKTYVI</span>
             </div>
          </div>
        </header>

        <div className="p-6 md:p-10 flex-1 overflow-y-auto w-full">
          <div className="max-w-7xl mx-auto">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Mail, 
  Send, 
  Copy, 
  Check, 
  ChevronRight, 
  Filter, 
  Edit3, 
  FileText, 
  ExternalLink,
  Tag,
  Info
} from 'lucide-react';
import { INITIAL_TEMPLATES } from '../constants';
import { EmailTemplate, TemplateCategory } from '../types';

const TemplatesTab: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<TemplateCategory | 'Visi'>('Visi');
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate | null>(null);
  const [editableBody, setEditableBody] = useState('');
  const [editableSubject, setEditableSubject] = useState('');
  const [copied, setCopied] = useState(false);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(INITIAL_TEMPLATES.map(t => t.category)));
    return ['Visi', ...cats];
  }, []);

  const filteredTemplates = useMemo(() => {
    return INITIAL_TEMPLATES.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           t.subject.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCat = selectedCategory === 'Visi' || t.category === selectedCategory;
      return matchesSearch && matchesCat;
    });
  }, [searchTerm, selectedCategory]);

  const handleSelectTemplate = (t: EmailTemplate) => {
    setSelectedTemplate(t);
    setEditableBody(t.body);
    setEditableSubject(t.subject);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(editableBody);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSend = () => {
    if (!selectedTemplate) return;

    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const subject = encodeURIComponent(editableSubject);
    const body = encodeURIComponent(editableBody);

    const mailtoUrl = `mailto:${to}?cc=${cc}&subject=${subject}&body=${body}`;
    window.location.href = mailtoUrl;
  };

  const editUrl = "https://docs.google.com/document/d/171tuL9pKuBYC376oxjoqmdM9NSqfAsinSpHJoyk2m8Y/edit";

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-[calc(100vh-180px)] animate-in fade-in duration-500">
      {/* Sidebar: List of Templates */}
      <div className="lg:col-span-4 flex flex-col space-y-4 min-h-0">
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm space-y-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Ieškoti šablono..."
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-emerald-500/10 text-sm font-medium"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex flex-wrap gap-2">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat as any)}
                className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all border ${
                  selectedCategory === cat 
                    ? 'bg-emerald-600 border-emerald-600 text-white shadow-md shadow-emerald-600/20' 
                    : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto bg-white rounded-3xl border border-slate-200 shadow-sm p-2 scrollbar-thin">
          {filteredTemplates.map(t => (
            <button
              key={t.id}
              onClick={() => handleSelectTemplate(t)}
              className={`w-full text-left p-4 rounded-2xl transition-all mb-1 group flex items-start space-x-3 ${
                selectedTemplate?.id === t.id ? 'bg-emerald-50 border-emerald-100 shadow-sm' : 'hover:bg-slate-50'
              }`}
            >
              <div className={`p-2 rounded-xl flex-shrink-0 ${selectedTemplate?.id === t.id ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white transition-colors'}`}>
                <FileText size={18} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between mb-0.5">
                  <h4 className={`text-[13px] font-bold truncate ${selectedTemplate?.id === t.id ? 'text-emerald-900' : 'text-slate-700'}`}>{t.title}</h4>
                  {t.level && (
                    <span className={`text-[9px] font-black px-1.5 py-0.5 rounded ml-2 ${
                      t.level === 'A' ? 'bg-blue-100 text-blue-700' : 
                      t.level === 'B' ? 'bg-orange-100 text-orange-700' : 'bg-red-100 text-red-700'
                    }`}>
                      {t.level}
                    </span>
                  )}
                </div>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{t.recipientType}</p>
              </div>
              <ChevronRight size={14} className={`mt-1 transition-transform ${selectedTemplate?.id === t.id ? 'text-emerald-400 translate-x-1' : 'text-slate-300'}`} />
            </button>
          ))}
          {filteredTemplates.length === 0 && (
            <div className="p-10 text-center">
              <p className="text-sm text-slate-400 font-medium">Šablonų nerasta</p>
            </div>
          )}
        </div>

        <a 
          href={editUrl} 
          target="_blank" 
          className="flex items-center justify-center space-x-2 py-3 bg-slate-800 text-white rounded-2xl text-[11px] font-bold uppercase tracking-widest hover:bg-black transition-colors shadow-lg"
        >
          <ExternalLink size={14} />
          <span>Redaguoti pagrindinį doką</span>
        </a>
      </div>

      {/* Main Area: Editor */}
      <div className="lg:col-span-8 flex flex-col min-h-0">
        {selectedTemplate ? (
          <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-sm flex-1 flex flex-col overflow-hidden">
            <div className="p-8 border-b border-slate-100 bg-slate-50/30">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div>
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="bg-emerald-100 text-emerald-700 text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-wider">{selectedTemplate.category}</span>
                    <span className="text-slate-300 text-xs">•</span>
                    <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">Gavėjas: {selectedTemplate.recipientType}</span>
                  </div>
                  <h3 className="text-2xl font-black text-slate-900 tracking-tight">{selectedTemplate.title}</h3>
                </div>
                <div className="flex items-center space-x-2">
                  <button 
                    onClick={handleCopy}
                    className="flex items-center space-x-2 px-4 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-sm font-bold hover:bg-slate-50 transition-all shadow-sm"
                  >
                    {copied ? <Check size={16} className="text-emerald-500" /> : <Copy size={16} />}
                    <span>{copied ? 'Nukopijuota' : 'Kopijuoti'}</span>
                  </button>
                  <button 
                    onClick={handleSend}
                    className="flex items-center space-x-2 px-6 py-2.5 bg-emerald-600 text-white rounded-xl text-sm font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/20"
                  >
                    <Send size={16} />
                    <span>Siųsti per Gmail</span>
                  </button>
                </div>
              </div>

              <div className="space-y-3">
                <div className="flex items-center bg-white p-3 rounded-xl border border-slate-200">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest w-20">Tema:</span>
                  <input 
                    className="flex-1 bg-transparent border-none outline-none text-sm font-bold text-slate-700"
                    value={editableSubject}
                    onChange={e => setEditableSubject(e.target.value)}
                  />
                </div>
                <div className="flex items-center bg-white p-3 rounded-xl border border-slate-200">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest w-20">Kam (CC):</span>
                  <span className="text-sm font-medium text-slate-500">{selectedTemplate.cc || 'Nėra'}</span>
                </div>
              </div>
            </div>

            <div className="flex-1 p-8 relative">
              <div className="absolute top-4 right-8 pointer-events-none">
                <Edit3 className="text-slate-100" size={100} />
              </div>
              <textarea 
                className="w-full h-full bg-transparent border-none outline-none resize-none text-slate-700 leading-relaxed font-medium text-lg placeholder-slate-300 relative z-10"
                value={editableBody}
                onChange={e => setEditableBody(e.target.value)}
                placeholder="Rašykite laišką čia..."
              />
            </div>

            <div className="p-6 bg-amber-50 border-t border-amber-100 flex items-start space-x-4">
              <div className="bg-amber-100 p-2 rounded-lg text-amber-700"><Info size={20} /></div>
              <div className="text-xs text-amber-900 leading-relaxed font-medium">
                <strong className="block mb-1 uppercase tracking-wider">Patarimas:</strong>
                Pakeiskite skliausteliuose esančią informaciją (pvz., [Vardas], [Data]) prieš siųsdami. Paspaudus „Siųsti“, sistema sugeneruos `mailto:` nuorodą jūsų numatytajai pašto programai.
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white border-2 border-dashed border-slate-200 rounded-[2.5rem] flex-1 flex flex-col items-center justify-center p-12 text-center opacity-60">
            <div className="bg-slate-50 p-6 rounded-full mb-6 text-slate-300">
              <Mail size={60} />
            </div>
            <h3 className="text-xl font-bold text-slate-900 mb-2">Pasirinkite šabloną</h3>
            <p className="text-sm text-slate-500 max-w-xs">Pasirinkite šabloną iš kairėje esančio sąrašo, kad galėtumėte jį redaguoti ir išsiųsti.</p>
          </div>
        )}
      </div>
    </div>
  );
};

