import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Modality } from "@google/genai";
import { Send, Sparkles, Volume2, User, Bot, Loader2, BrainCircuit, HeartPulse } from 'lucide-react';

const AIAssistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; audio?: string }[]>([
    { role: 'bot', text: 'Sveiki. Esu Antakalnio progimnazijos DI pagalbininkas. Kaip galiu Jums padėti šiandien? Galiu patarti dėl situacijų valdymo, emocinio palaikymo ar tinkamiausio komunikacijos būdo.' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const decodeAudio = async (base64Audio: string) => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioContextRef.current;

    const binaryString = atob(base64Audio);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    const dataInt16 = new Int16Array(bytes.buffer);
    const frameCount = dataInt16.length;
    const buffer = ctx.createBuffer(1, frameCount, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  const playAudio = async (base64Audio: string) => {
    try {
      setIsSpeaking(true);
      const buffer = await decodeAudio(base64Audio);
      const ctx = audioContextRef.current!;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (e) {
      console.error("Audio playback error:", e);
      setIsSpeaking(false);
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Step 1: Generate Text Response
      const textResponse = await ai.models.generateContent({
        model: 'gemini-2.0-flash-exp',
        contents: userMessage,
        config: {
          systemInstruction: `Esi profesionalus Vilniaus Antakalnio progimnazijos pagalbos asistentas. 
          Tavo tikslas - teikti trumpus, aiškius ir empatiškus patarimus mokytojams ir tėvams. 
          Remkis saugumo protokolais (UAK), pozityvios disciplinos principais ir pagalbasau.lt dvasia (rūpestis psichine sveikata). 
          Atsakyk lietuvių kalba. Būk konkretus. Jei situacija kritinė (smurtas, savižudybė), visada primink skambinti 112 arba kviesti budintį vadovą.`,
        }
      });

      const botText = textResponse.text || "Apgailestauju, nepavyko sugeneruoti atsakymo.";

      // Step 2: Generate Audio for the response (TTS)
      let audioBase64 = "";
      try {
        const ttsResponse = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: `Perskaityk ramiai ir palaikančiai: ${botText}` }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
            },
          },
        });
        audioBase64 = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
      } catch (e) {
        console.warn("TTS fail:", e);
      }

      setMessages(prev => [...prev, { role: 'bot', text: botText, audio: audioBase64 }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: 'Atsiprašau, įvyko ryšio klaida. Prašome pabandyti dar kartą.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-4xl mx-auto animate-in fade-in duration-700">
      {/* Header Info */}
      <div className="bg-gradient-to-br from-amber-500 to-orange-600 p-6 rounded-t-[2.5rem] text-white shadow-xl shadow-amber-500/10">
        <div className="flex items-center space-x-4">
          <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-md">
            <BrainCircuit size={32} />
          </div>
          <div>
            <h2 className="text-xl font-black uppercase tracking-tight">DI Pagalbininkas</h2>
            <div className="flex items-center space-x-2 text-amber-100 text-[10px] font-bold uppercase tracking-widest mt-1">
              <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
              <span>Remiamasi PagalbaSau.lt principais</span>
            </div>
          </div>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 bg-white border-x border-slate-200 overflow-y-auto p-6 space-y-6 scrollbar-thin">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`flex items-start space-x-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`p-2 rounded-xl flex-shrink-0 ${msg.role === 'user' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                {msg.role === 'user' ? <User size={20} /> : <Bot size={20} />}
              </div>
              <div className={`p-4 rounded-2xl shadow-sm border ${
                msg.role === 'user' 
                  ? 'bg-emerald-600 text-white border-emerald-500 rounded-tr-none' 
                  : 'bg-slate-50 text-slate-800 border-slate-100 rounded-tl-none'
              }`}>
                <p className="text-sm font-medium leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                {msg.audio && (
                  <button 
                    onClick={() => playAudio(msg.audio!)}
                    disabled={isSpeaking}
                    className={`mt-3 flex items-center space-x-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                      msg.role === 'user' 
                        ? 'bg-emerald-500 hover:bg-emerald-400 text-white' 
                        : 'bg-white border border-amber-200 text-amber-700 hover:bg-amber-50'
                    }`}
                  >
                    <Volume2 size={14} />
                    <span>{isSpeaking ? 'Garsas...' : 'Klausyti patarimo'}</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center space-x-2">
              <Loader2 size={16} className="animate-spin text-amber-500" />
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">DI mąsto...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-slate-50 p-6 rounded-b-[2.5rem] border border-slate-200 shadow-inner">
        <div className="flex items-center space-x-3 bg-white p-2 rounded-2xl shadow-sm border border-slate-200 focus-within:ring-2 focus-within:ring-amber-500/20 transition-all">
          <input 
            type="text" 
            placeholder="Aprašykite situaciją arba užduokite klausimą..."
            className="flex-1 bg-transparent px-4 py-2 outline-none text-sm font-medium text-slate-700"
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSend()}
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            className={`p-3 rounded-xl transition-all ${
              input.trim() && !isLoading 
                ? 'bg-amber-600 text-white shadow-lg shadow-amber-600/20 hover:scale-105' 
                : 'bg-slate-100 text-slate-300'
            }`}
          >
            <Send size={20} />
          </button>
        </div>
        <div className="mt-4 flex items-center justify-center space-x-6 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
          <div className="flex items-center space-x-1">
            <Sparkles size={12} className="text-amber-500" />
            <span>Greiti patarimai</span>
          </div>
          <div className="flex items-center space-x-1">
            <HeartPulse size={12} className="text-red-400" />
            <span>Emocinis palaikymas</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

