import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GoogleGenAI, Modality, LiveServerMessage } from "@google/genai";
import { Send, Sparkles, Volume2, User, Bot, Loader2, BrainCircuit, HeartPulse, Coffee, Mic, MicOff, PhoneCall, Siren } from 'lucide-react';

const AIAssistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; audio?: string }[]>([
    { role: 'bot', text: 'Sveiki. Esu Jūsų emocinė pagalvėlė 🛋️. Kai darbe tampa per karšta arba nežinote, kaip reaguoti į situaciją, aš čia. Galite man rašyti arba tiesiog išsikalbėti paspaudę mikrofono piktogramą. Kuo galiu pasitarnauti?' }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);

  // Audio playback state for Live API (if used)
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const decodeAudio = async (base64Audio: string) => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioContextRef.current;

    const binaryString = atob(base64Audio);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    const dataInt16 = new Int16Array(bytes.buffer);
    const frameCount = dataInt16.length;
    const buffer = ctx.createBuffer(1, frameCount, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  const playAudio = async (base64Audio: string) => {
    try {
      setIsSpeaking(true);
      const buffer = await decodeAudio(base64Audio);
      const ctx = audioContextRef.current!;
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (e) {
      console.error("Audio playback error:", e);
      setIsSpeaking(false);
    }
  };

  const systemInstruction = `Esi „DI emocinė pagalvėlė“ Vilniaus Antakalnio progimnazijoje. 
  Tavo charakteris: empatiškas, raminantis, bet griežtai besilaikantis saugumo schemų. 
  STRESINĖSE SITUACIJOSE VEIK PAGAL ŠIAS SCHEMAS:
  1. UAK (Ugdymo aplinkos keitimas): Jei mokinys trukdo pamoką, pirmiausia 2-3 žodinės pastabos. Jei nepadeda - kviečiamas budintis vadovas palydėti mokinį savarankiškam darbui.
  2. SOS (Suicidinis pavojus): Nepalik mokinio vieno! Kviesk psichologą, socialinį pedagogą arba vadovą. Jei bando žalotis - skubiai 112.
  3. SMURTAS / GINČAS: Nedelsiant atskirti dalyvius. Kviesti slaugytoją ir budintį vadovą. Informuoti tėvus.
  4. PSICHOAKTYVIOS MEDŽIAGOS: Įtarus vartojimą - palydėti pas sveikatos specialistą. Radus daiktų - 3 asmenų komisija, tėvų informavimas.
  Tavo tikslas - nuraminti mokytoją, pripažinti jo nuovargį ar stresą, ir tada pasiūlyti konkretų šių schemų žingsnį. 
  Atsakyk lietuvių kalba, švelniai, su empatija. Jei situacija pavojinga gyvybei, skatink spausti SOS 112 mygtuką.`;

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input.trim();
    if (!textToSend || isLoading) return;

    if (!textOverride) setInput('');
    setMessages(prev => [...prev, { role: 'user', text: textToSend }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const textResponse = await ai.models.generateContent({
        model: 'gemini-2.0-flash-exp',
        contents: textToSend,
        config: { systemInstruction }
      });

      const botText = textResponse.text || "Atsiprašau, trumpam užsnūdau. Ar galėtumėte pakartoti?";

      let audioBase64 = "";
      try {
        const ttsResponse = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: `Perskaityk švelniu ir ramiu balsu: ${botText}` }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
            },
          },
        });
        audioBase64 = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
      } catch (e) {
        console.warn("TTS fail:", e);
      }

      setMessages(prev => [...prev, { role: 'bot', text: botText, audio: audioBase64 }]);
      if (audioBase64) playAudio(audioBase64);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: 'Ups, mano laidai susipainiojo. Pabandykime dar kartą po akimirkos.' }]);
    } finally {
      setIsLoading(false);
    }
  };

  const startVoiceMode = async () => {
    if (isListening) {
      stopVoiceMode();
      return;
    }

    try {
      setIsListening(true);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      let currentInputTranscription = '';
      let currentOutputTranscription = '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const inputAudioContext = new AudioContext({ sampleRate: 16000 });
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const base64 = btoa(String.fromCharCode(...new Uint8Array(int16.buffer)));
              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: { data: base64, mimeType: 'audio/pcm;rate=16000' } });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              currentInputTranscription += message.serverContent.inputTranscription.text;
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscription += message.serverContent.outputTranscription.text;
            }

            if (message.serverContent?.turnComplete) {
              const userT = currentInputTranscription;
              const botT = currentOutputTranscription;
              if (userT) setMessages(prev => [...prev, { role: 'user', text: userT }]);
              if (botT) setMessages(prev => [...prev, { role: 'bot', text: botT }]);
              currentInputTranscription = '';
              currentOutputTranscription = '';
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              if (!audioContextRef.current) audioContextRef.current = new AudioContext({ sampleRate: 24000 });
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudio(base64Audio);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onclose: () => setIsListening(false),
          onerror: () => setIsListening(false)
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {}
        }
      });
      liveSessionRef.current = sessionPromise;
    } catch (err) {
      console.error("Microphone error:", err);
      setIsListening(false);
    }
  };

  const stopVoiceMode = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.then((session: any) => session.close());
    }
    setIsListening(false);
  };

  const handleSOS = () => {
    if (confirm("DĖMESIO! Ar tikrai norite skambinti skubios pagalbos tarnybai 112?")) {
      window.location.href = "tel:112";
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-4xl mx-auto animate-in fade-in duration-700">
      {/* Header Info with SOS */}
      <div className="bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 p-6 rounded-t-[2.5rem] text-white shadow-xl relative">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="bg-white/20 p-3 rounded-2xl backdrop-blur-md">
              <Sparkles size={32} />
            </div>
            <div>
              <h2 className="text-xl font-black uppercase tracking-tight">DI emocinė pagalvėlė 🛋️✨🧸</h2>
              <div className="flex items-center space-x-2 text-indigo-100 text-[10px] font-bold uppercase tracking-widest mt-1">
                <span className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse"></span>
                <span>Visada pasiruošusi išklausyti</span>
              </div>
            </div>
          </div>

          <button 
            onClick={handleSOS}
            className="flex items-center space-x-2 bg-red-600 hover:bg-red-700 text-white px-5 py-3 rounded-2xl shadow-lg shadow-red-600/30 transition-all font-black uppercase tracking-widest text-sm border-2 border-red-400"
          >
            <PhoneCall size={20} className="animate-bounce" />
            <span>SOS 112</span>
          </button>
        </div>
      </div>

      {/* Chat Area */}
      <div className="flex-1 bg-white border-x border-slate-200 overflow-y-auto p-6 space-y-6 scrollbar-thin">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`flex items-start space-x-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`p-2 rounded-xl flex-shrink-0 ${msg.role === 'user' ? 'bg-indigo-100 text-indigo-700' : 'bg-pink-100 text-pink-700'}`}>
                {msg.role === 'user' ? <User size={20} /> : <Coffee size={20} />}
              </div>
              <div className={`p-4 rounded-2xl shadow-sm border ${
                msg.role === 'user' 
                  ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                  : 'bg-slate-50 text-slate-800 border-slate-100 rounded-tl-none'
              }`}>
                <p className="text-sm font-medium leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                {msg.audio && !isListening && (
                  <button 
                    onClick={() => playAudio(msg.audio!)}
                    disabled={isSpeaking}
                    className={`mt-3 flex items-center space-x-2 px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                      msg.role === 'user' 
                        ? 'bg-indigo-500 hover:bg-indigo-400 text-white' 
                        : 'bg-white border border-pink-200 text-pink-700 hover:bg-pink-50'
                    }`}
                  >
                    <Volume2 size={14} />
                    <span>{isSpeaking ? 'Pagalvėlė kalba...' : 'Paklausyti dar kartą'}</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center space-x-2">
              <Loader2 size={16} className="animate-spin text-purple-500" />
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest italic">Purenama pagalvėlė...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-slate-50 p-6 rounded-b-[2.5rem] border border-slate-200 shadow-inner">
        <div className="flex items-center space-x-3">
          <button 
            onClick={startVoiceMode}
            className={`p-4 rounded-2xl shadow-lg transition-all ${
              isListening 
                ? 'bg-red-500 text-white animate-pulse' 
                : 'bg-white text-indigo-600 border border-slate-200 hover:bg-slate-50'
            }`}
          >
            {isListening ? <MicOff size={24} /> : <Mic size={24} />}
          </button>

          <div className="flex-1 flex items-center space-x-3 bg-white p-2 rounded-2xl shadow-sm border border-slate-200 focus-within:ring-2 focus-within:ring-indigo-500/20 transition-all">
            <input 
              type="text" 
              placeholder={isListening ? "Išklausau Jus..." : "Pasidalykite situacija..."}
              className="flex-1 bg-transparent px-4 py-2 outline-none text-sm font-medium text-slate-700 disabled:opacity-50"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
              disabled={isListening}
            />
            <button 
              onClick={() => handleSend()}
              disabled={!input.trim() || isLoading || isListening}
              className={`p-3 rounded-xl transition-all ${
                input.trim() && !isLoading && !isListening
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20 hover:scale-105' 
                  : 'bg-slate-100 text-slate-300'
              }`}
            >
              <Send size={20} />
            </button>
          </div>
        </div>

        <div className="mt-4 flex items-center justify-center space-x-6 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
          <div className="flex items-center space-x-1">
            <HeartPulse size={12} className="text-pink-500" />
            <span>PagalbaSau.lt dvasia</span>
          </div>
          <div className="flex items-center space-x-1">
            <Siren size={12} className="text-red-400" />
            <span>Saugumo schemos</span>
          </div>
          <div className="flex items-center space-x-1">
            <BrainCircuit size={12} className="text-indigo-400" />
            <span>Balso atpažinimas</span>
          </div>
        </div>
      </div>
    </div>
  );
};

