                        : 'bg-white border border-pink-200 text-pink-700 hover:bg-pink-50'
                    }`}
                  >
                    <Volume2 size={14} />
                    <span>{isSpeaking ? 'Pagalvėlė kalba...' : 'Paklausyti dar kartą'}</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center space-x-2">
              <Loader2 size={16} className="animate-spin text-purple-500" />
