                <Heart size={20} fill="currentColor" fillOpacity={0.1} />
              </div>
              <div className="pr-4">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-0.5">Gilesnė savipagalba</p>
                <p className="text-[13px] font-bold text-slate-600 group-hover:text-slate-900 transition-colors leading-tight">Ieškote daugiau resursų savijautai?</p>
              </div>
           </div>
           <a 
              href="https://pagalbasau.lt/" 
              target="_blank" 
              className="flex items-center space-x-2 px-4 py-2 bg-white border border-slate-200 text-slate-500 hover:text-indigo-600 hover:border-indigo-100 rounded-xl text-xs font-bold transition-all shadow-sm"
            >
