// Pagalbinės funkcijos pagal Gemini API gaires
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const STORAGE_KEY = 'vap_ai_chat_history';
const INITIAL_MESSAGE = { role: 'bot' as const, text: 'Sveiki. Esu Jūsų emocinė pagalvėlė 🛋️. Kai darbe tampa per karšta arba nežinote, kaip reaguoti į situaciją, aš čia. Galite man rašyti arba tiesiog išsikalbėti paspaudę mikrofono piktogramą. Kuo galiu pasitarnauti?' };

interface AIAssistantProps {
  contextTab?: string;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ contextTab = 'dashboard' }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; audio?: string }[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [INITIAL_MESSAGE];
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isMuted, setIsMuted] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  const playAudio = async (base64Audio: string) => {
    if (isMuted) return;
    try {
      setIsSpeaking(true);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBytes = decode(base64Audio);
      const buffer = await decodeAudioData(audioBytes, ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (e) {
      console.error("Audio playback error:", e);
      setIsSpeaking(false);
    }
  };

  const systemInstruction = useMemo(() => {
    const specialistsContext = INITIAL_SPECIALISTS.map(s => `${s.name} (${s.category}, ${s.classes}, kab. ${s.office}, tel. ${s.phone})`).join('\n');
    const templatesContext = INITIAL_TEMPLATES.map(t => `${t.title} (${t.category}, recipient: ${t.recipientType})`).join('\n');

    return `Esi „DI emocinė pagalvėlė“ Vilniaus Antakalnio progimnazijoje. 
    Tavo charakteris: empatiškas, raminantis, bet griežtai besilaikantis saugumo schemų. 
    REMKIS PagalbaSau.lt MEDŽIAGA.
    AKTUALUS KONTEKSTAS: Vartotojas šiuo metu lankosi "${contextTab}" skiltyje.
    SPECIALISTAI: ${specialistsContext}
    LAIŠKŲ ŠABLONAI: ${templatesContext}
    Atsakyk trumpai, lietuviškai, su atjauta.`;
  }, [contextTab]);

  const quickQuestions = useMemo(() => {
    switch (contextTab) {
      case 'contacts': return ["Kas yra psichologas?", "Raštinės kontaktai", "Kur rasti vadovus?"];
      case 'templates': return ["Laiškas dėl lankomumo", "Šablonas patyčioms", "Kaip siųsti laišką?"];
      case 'schemes': return ["Trukdymas pamokai", "Kas yra UAK?", "Budinčio vadovo vaidmuo"];
      default: return ["Kaip veikia sistema?", "Noriu pasikalbėti", "Budėjimo grafikas"];
    }
  }, [contextTab]);

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input.trim();
    if (!textToSend || isLoading) return;

    if (!textOverride) setInput('');
    setMessages(prev => [...prev, { role: 'user', text: textToSend }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const streamResponse = await ai.models.generateContentStream({
        model: 'gemini-3-flash-preview',
        contents: textToSend,
        config: { systemInstruction }
      });

      let fullBotText = "";
      setMessages(prev => [...prev, { role: 'bot', text: "" }]);

      for await (const chunk of streamResponse) {
        fullBotText += chunk.text || "";
        setMessages(prev => {
          const newMessages = [...prev];
          newMessages[newMessages.length - 1] = { ...newMessages[newMessages.length - 1], text: fullBotText };
          return newMessages;
        });
      }
      setIsLoading(false);

      if (!isMuted) {
        try {
          const ttsResponse = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: fullBotText }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
          });
          const audioBase64 = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
          if (audioBase64) {
            setMessages(prev => {
              const newMessages = [...prev];
              newMessages[newMessages.length - 1] = { ...newMessages[newMessages.length - 1], audio: audioBase64 };
              return newMessages;
            });
            playAudio(audioBase64);
          }
        } catch (e) {}
      }
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: 'Klaida susisiekiant su DI.' }]);
      setIsLoading(false);
    }
  };

  const clearHistory = () => {
    if (confirm("Ištrinti istoriją?")) {
      setMessages([INITIAL_MESSAGE]);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-5xl mx-auto animate-in fade-in duration-700 bg-white rounded-[3rem] shadow-2xl border border-slate-100 overflow-hidden">
      {/* Header */}
      <div className="bg-slate-900 p-8 text-white relative">
        <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none">
          <BrainCircuit size={120} />
        </div>
        <div className="relative z-10 flex items-center justify-between">
          <div className="flex items-center space-x-5">
            <div className="w-14 h-14 bg-white/10 rounded-2xl backdrop-blur-md flex items-center justify-center border border-white/20">
              <Sparkles className="text-amber-400" size={28} />
            </div>
            <div>
              <h2 className="text-2xl font-black tracking-tight">DI EMOCINĖ PAGALVĖLĖ</h2>
              <div className="flex items-center space-x-2 text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">
                <span className={`w-2 h-2 rounded-full ${isListening ? 'bg-rose-500 animate-ping' : 'bg-emerald-500'}`}></span>
                <span>{isListening ? 'Klausausi...' : 'Paruošta pokalbiui'}</span>
              </div>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <button onClick={clearHistory} className="p-3 bg-white/5 hover:bg-rose-500/20 rounded-xl transition-all">
              <Trash2 size={20} />
            </button>
            <button onClick={() => setIsMuted(!isMuted)} className={`p-3 rounded-xl transition-all ${isMuted ? 'bg-rose-500/20 text-rose-400' : 'bg-white/5 text-white'}`}>
              {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
            </button>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-8 space-y-8 scrollbar-thin flex flex-col bg-slate-50/30">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex items-start space-x-4 max-w-[80%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 shadow-sm ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>
                {msg.role === 'user' ? <User size={18} /> : <Coffee size={18} />}
              </div>
              <div className={`p-6 rounded-[2rem] shadow-sm leading-relaxed text-[15px] font-medium ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-white text-slate-700 border border-slate-100'}`}>
                {msg.text}
                {msg.audio && !isMuted && (
                  <button onClick={() => playAudio(msg.audio!)} className="mt-4 flex items-center space-x-2 text-[10px] font-black uppercase tracking-widest opacity-60 hover:opacity-100 transition-opacity">
                    <Volume2 size={12} />
                    <span>Paklausyti</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
        {isLoading && !messages[messages.length-1].text && (
          <div className="flex justify-start">
            <div className="bg-white p-5 rounded-[2rem] border border-slate-100 flex items-center space-x-3 shadow-sm">
              <Loader2 size={18} className="animate-spin text-slate-400" />
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">DI mąsto...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-8 bg-white border-t border-slate-100">
        <div className="flex items-center space-x-3 mb-6 overflow-x-auto pb-2 no-scrollbar">
          {quickQuestions.map((q, idx) => (
            <button key={idx} onClick={() => handleSend(q)} className="flex-shrink-0 px-5 py-2.5 bg-slate-50 border border-slate-100 rounded-full text-[11px] font-extrabold text-slate-500 hover:bg-slate-900 hover:text-white hover:border-slate-900 transition-all uppercase tracking-wider">
              {q}
            </button>
          ))}
        </div>

        <div className="flex items-center space-x-4">
          <div className="flex-1 flex items-center bg-slate-50 border border-slate-200 rounded-[2rem] px-6 py-2 focus-within:ring-4 focus-within:ring-slate-900/5 transition-all">
            <input 
              type="text" 
              placeholder="Parašykite čia..."
              className="flex-1 bg-transparent py-4 outline-none text-[15px] font-medium"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
            />
            <button onClick={() => handleSend()} className={`p-3 rounded-2xl transition-all ${input.trim() ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-200 text-slate-400'}`}>
              <Send size={20} />
            </button>
          </div>
          <button onClick={() => setIsListening(!isListening)} className={`p-5 rounded-[2rem] transition-all shadow-lg ${isListening ? 'bg-rose-500 text-white animate-pulse' : 'bg-white border border-slate-200 text-slate-900 hover:bg-slate-50'}`}>
            {isListening ? <MicOff size={24} /> : <Mic size={24} />}
          </button>
        </div>
      </div>
    </div>
  );
};

