function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const STORAGE_KEY = 'vap_ai_chat_history';
const INITIAL_MESSAGE = { role: 'bot' as const, text: 'Sveiki. Esu Jūsų emocinė pagalvėlė 🛋️. Kai darbe tampa per karšta arba nežinote, kaip reaguoti, aš čia.' };

interface AIAssistantProps {
  contextTab?: string;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ contextTab = 'dashboard' }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<{ role: 'user' | 'bot'; text: string; audio?: string }[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [INITIAL_MESSAGE];
  });

  const [isLoading, setIsLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isMuted, setIsMuted] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const liveSessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  const getAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    return audioContextRef.current;
  };

  const playAudio = async (base64Audio: string) => {
    if (isMuted) return;
    try {
      setIsSpeaking(true);
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') await ctx.resume();
      const audioBytes = decode(base64Audio);
      const buffer = await decodeAudioData(audioBytes, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setIsSpeaking(false);
      source.start();
    } catch (e) {
      setIsSpeaking(false);
    }
  };

  const systemInstruction = useMemo(() => {
    const specialistsContext = INITIAL_SPECIALISTS.map(s => `${s.name} (${s.office}, ${s.phone})`).join('\n');
    return `Esi „DI emocinė pagalvėlė“ Vilniaus Antakalnio progimnazijoje. Empatiškas, raminantis. Vartotojas skiltyje: "${contextTab}". SPECIALISTAI: ${specialistsContext}. Atsakyk trumpai, lietuviškai.`;
  }, [contextTab]);

  const quickQuestions = useMemo(() => {
    switch (contextTab) {
      case 'contacts': return ["Kas yra psichologas?", "Raštinė", "Vadovai"];
      case 'templates': return ["Lankomumas", "Patyčios", "Siuntimas"];
      default: return ["Kaip veikia?", "Noriu pasikalbėti"];
    }
  }, [contextTab]);

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input.trim();
    if (!textToSend || isLoading) return;
    if (!textOverride) setInput('');
    setMessages(prev => [...prev, { role: 'user', text: textToSend }]);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const streamResponse = await ai.models.generateContentStream({
        model: 'gemini-3-flash-preview',
        contents: textToSend,
        config: { systemInstruction }
      });

      let fullBotText = "";
      setMessages(prev => [...prev, { role: 'bot', text: "" }]);
      for await (const chunk of streamResponse) {
        fullBotText += chunk.text || "";
        setMessages(prev => {
          const newMessages = [...prev];
          newMessages[newMessages.length - 1] = { ...newMessages[newMessages.length - 1], text: fullBotText };
          return newMessages;
        });
      }
      setIsLoading(false);

      if (!isMuted) {
        try {
          const ttsResponse = await ai.models.generateContent({
            model: "gemini-2.5-flash-preview-tts",
            contents: [{ parts: [{ text: fullBotText }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
            },
          });
          const audioBase64 = ttsResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
          if (audioBase64) {
            setMessages(prev => {
              const newMessages = [...prev];
              newMessages[newMessages.length - 1] = { ...newMessages[newMessages.length - 1], audio: audioBase64 };
              return newMessages;
            });
            playAudio(audioBase64);
          }
        } catch (e) {}
      }
    } catch (error) {
      setIsLoading(false);
    }
  };

  const clearHistory = () => {
    if (confirm("Ištrinti?")) {
      setMessages([INITIAL_MESSAGE]);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)] max-w-4xl mx-auto animate-in fade-in duration-500 bg-white rounded-[2rem] shadow-lg border border-slate-100 overflow-hidden">
      {/* Compact Header */}
      <div className="bg-slate-900 p-6 text-white relative">
        <div className="relative z-10 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="w-10 h-10 bg-white/10 rounded-xl backdrop-blur-md flex items-center justify-center border border-white/20">
              <Sparkles className="text-amber-400" size={20} />
            </div>
            <div>
              <h2 className="text-lg font-black tracking-tight uppercase">DI EMOCINĖ PAGALVĖLĖ</h2>
              <p className="text-[8px] text-slate-400 font-black uppercase tracking-widest">Paruošta pokalbiui</p>
            </div>
          </div>
          <div className="flex items-center space-x-1.5">
            <button onClick={clearHistory} className="p-2 bg-white/5 hover:bg-rose-500/20 rounded-lg transition-all">
              <Trash2 size={16} />
            </button>
            <button onClick={() => setIsMuted(!isMuted)} className={`p-2 rounded-lg transition-all ${isMuted ? 'bg-rose-500/20 text-rose-400' : 'bg-white/5 text-white'}`}>
              {isMuted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
          </div>
        </div>
      </div>

      {/* Messages - Optimized Spacing */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-thin flex flex-col bg-slate-50/20">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`flex items-start space-x-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 shadow-sm ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>
                {msg.role === 'user' ? <User size={14} /> : <Coffee size={14} />}
              </div>
              <div className={`p-4 rounded-2xl shadow-sm text-sm font-medium ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-white text-slate-700 border border-slate-100'}`}>
                {msg.text}
                {msg.audio && !isMuted && (
                  <button onClick={() => playAudio(msg.audio!)} className="mt-2 flex items-center space-x-1.5 text-[9px] font-black uppercase tracking-widest opacity-50 hover:opacity-100 transition-opacity">
                    <Volume2 size={10} />
                    <span>Klausyti</span>
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
        {isLoading && !messages[messages.length-1].text && (
          <div className="flex justify-start">
            <div className="bg-white p-3 rounded-2xl border border-slate-100 flex items-center space-x-2 shadow-sm">
              <Loader2 size={14} className="animate-spin text-slate-400" />
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">DI mąsto...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area - Compact */}
      <div className="p-6 bg-white border-t border-slate-100">
        <div className="flex items-center space-x-2 mb-4 overflow-x-auto pb-1 no-scrollbar">
          {quickQuestions.map((q, idx) => (
            <button key={idx} onClick={() => handleSend(q)} className="flex-shrink-0 px-3 py-1.5 bg-slate-50 border border-slate-100 rounded-lg text-[9px] font-extrabold text-slate-500 hover:bg-slate-900 hover:text-white transition-all uppercase tracking-wider">
              {q}
            </button>
          ))}
        </div>

        <div className="flex items-center space-x-3">
          <div className="flex-1 flex items-center bg-slate-50 border border-slate-200 rounded-xl px-4 py-1.5 focus-within:ring-2 focus-within:ring-slate-900/5 transition-all">
            <input 
              type="text" 
              placeholder="Parašykite..."
              className="flex-1 bg-transparent py-2.5 outline-none text-sm font-medium"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleSend()}
            />
            <button onClick={() => handleSend()} className={`p-2 rounded-lg transition-all ${input.trim() ? 'bg-slate-900 text-white shadow-md' : 'bg-slate-200 text-slate-400'}`}>
              <Send size={16} />
            </button>
          </div>
          <button onClick={() => setIsListening(!isListening)} className={`p-3.5 rounded-xl transition-all shadow-md ${isListening ? 'bg-rose-500 text-white animate-pulse' : 'bg-white border border-slate-200 text-slate-900 hover:bg-slate-50'}`}>
            {isListening ? <MicOff size={18} /> : <Mic size={18} />}
          </button>
        </div>
      </div>
    </div>
  );
};

