          return (
            <div key={s.id} className="bg-white border border-black/5 rounded-[2rem] overflow-hidden shadow-sm hover:border-black/10 transition-all flex flex-col h-full hover:-translate-y-0.5">
              <div className={`p-5 ${style.bg} border-b border-black/5 flex items-start justify-between relative`}>
