                  <div>
                    <span className={`inline-block px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-widest ${style.badge} mb-1 border border-black/5`}>
                      {s.category}
                    </span>
                    <h4 className="text-sm font-black text-black tracking-tight truncate max-w-[140px]">{s.name}</h4>
                  </div>
                </div>
              </div>

              <div className="p-5 flex-1 flex flex-col space-y-4">
                <div className="bg-slate-50/50 p-3 rounded-xl border border-black/5">
