import React, { useState, useMemo } from 'react';
import { 
  Search, 
  Mail, 
  Send, 
  Copy, 
  Check, 
  ChevronRight, 
  FileText, 
  ExternalLink,
  Info,
  Edit3
} from 'lucide-react';
import { INITIAL_TEMPLATES } from '../constants';
import { EmailTemplate, TemplateCategory } from '../types';

const TemplatesTab: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<TemplateCategory | 'Visi'>('Visi');
  const [selectedTemplate, setSelectedTemplate] = useState<EmailTemplate | null>(null);
  const [editableBody, setEditableBody] = useState('');
  const [editableSubject, setEditableSubject] = useState('');
  const [copied, setCopied] = useState(false);

  const categories = useMemo(() => {
    const cats = Array.from(new Set(INITIAL_TEMPLATES.map(t => t.category)));
    return ['Visi', ...cats];
  }, []);

  const filteredTemplates = useMemo(() => {
    return INITIAL_TEMPLATES.filter(t => {
      const matchesSearch = t.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           t.subject.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCat = selectedCategory === 'Visi' || t.category === selectedCategory;
      return matchesSearch && matchesCat;
    });
  }, [searchTerm, selectedCategory]);

  const handleSelectTemplate = (t: EmailTemplate) => {
    setSelectedTemplate(t);
    setEditableBody(t.body);
    setEditableSubject(t.subject);
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(editableBody);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleSend = () => {
    if (!selectedTemplate) return;
    const to = selectedTemplate.to || '';
    const cc = selectedTemplate.cc || '';
    const subject = encodeURIComponent(editableSubject);
    const body = encodeURIComponent(editableBody);
    window.location.href = `mailto:${to}?cc=${cc}&subject=${subject}&body=${body}`;
  };

  const editUrl = "https://docs.google.com/document/d/171tuL9pKuBYC376oxjoqmdM9NSqfAsinSpHJoyk2m8Y/edit";

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[calc(100vh-140px)] animate-in fade-in duration-500 overflow-hidden">
      {/* Sidebar: List of Templates */}
      <div className="lg:col-span-4 flex flex-col space-y-4 min-h-0 h-full">
        <div className="bg-white p-5 rounded-[1.5rem] border border-slate-100 shadow-sm space-y-4">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input 
              type="text" 
              placeholder="Ieškoti šablono..."
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl outline-none focus:border-green-700 transition-all text-sm font-bold"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex flex-wrap gap-1.5">
            {categories.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat as any)}
                className={`px-2.5 py-1 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all border ${
                  selectedCategory === cat 
                    ? 'bg-green-700 border-green-700 text-white shadow-md' 
                    : 'bg-white border-slate-100 text-slate-500 hover:border-green-700/20'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto bg-white rounded-[1.5rem] border border-slate-100 shadow-sm p-3 scrollbar-thin">
          <div className="space-y-1.5">
            {filteredTemplates.map(t => (
              <button
                key={t.id}
                onClick={() => handleSelectTemplate(t)}
                className={`w-full text-left p-3.5 rounded-xl transition-all flex items-start space-x-3 group border ${
                  selectedTemplate?.id === t.id 
                    ? 'bg-green-50 border-green-100 shadow-sm' 
                    : 'bg-white border-transparent hover:bg-slate-50'
                }`}
              >
                <div className={`p-2.5 rounded-lg flex-shrink-0 transition-all ${
                  selectedTemplate?.id === t.id ? 'bg-green-700 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-white'
                }`}>
                  <FileText size={18} />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-0.5">
                    <h4 className={`text-[13px] font-black truncate leading-tight ${selectedTemplate?.id === t.id ? 'text-green-900' : 'text-slate-800'}`}>
                      {t.title}
                    </h4>
                  </div>
                  <p className={`text-[9px] font-bold uppercase tracking-wider ${selectedTemplate?.id === t.id ? 'text-green-600/70' : 'text-slate-400'}`}>
                    {t.recipientType} • {t.category}
                  </p>
                </div>
                <ChevronRight size={14} className={`mt-2 transition-transform ${selectedTemplate?.id === t.id ? 'text-green-700 translate-x-1' : 'text-slate-200'}`} />
              </button>
            ))}
          </div>
        </div>

        <a 
          href={editUrl} 
          target="_blank" 
          className="flex items-center justify-center space-x-2 py-3.5 bg-green-700 text-white rounded-[1.25rem] text-[11px] font-black uppercase tracking-widest hover:bg-green-800 transition-all shadow-lg hover:-translate-y-0.5"
        >
          <Edit3 size={16} />
          <span>REDAGUOTI ŠABLONUS</span>
          <ExternalLink size={12} className="opacity-50" />
        </a>
      </div>

      {/* Main Area: Editor */}
      <div className="lg:col-span-8 flex flex-col min-h-0 h-full">
        {selectedTemplate ? (
          <div className="bg-white border border-slate-100 rounded-[2rem] shadow-sm flex-1 flex flex-col overflow-hidden relative">
            {/* Dark Header matched with Intro */}
            <div className="p-6 md:p-8 border-b border-green-800 bg-green-700 text-white">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                <div>
                  <div className="flex items-center space-x-2 mb-2">
                    <span className="bg-green-600/50 backdrop-blur-sm text-green-100 text-[8px] font-black px-2 py-0.5 rounded-md uppercase tracking-widest border border-white/10">
                      {selectedTemplate.category}
                    </span>
                    <span className="text-white/30">•</span>
                    <span className="text-white/60 text-[9px] font-black uppercase tracking-widest">
                      KAM: {selectedTemplate.recipientType}
                    </span>
                  </div>
                  <h3 className="text-2xl font-black text-white tracking-tight leading-tight uppercase">{selectedTemplate.title}</h3>
                </div>

                <div className="flex items-center space-x-2">
                  <button 
                    onClick={handleCopy}
                    className="flex items-center space-x-2 px-5 py-2.5 bg-white/10 hover:bg-white/20 border border-white/20 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm group"
                  >
                    {copied ? <Check size={16} className="text-green-300" /> : <Copy size={16} className="group-hover:rotate-6 transition-transform" />}
                    <span>{copied ? 'NUKOPIJUOTA' : 'KOPIJUOTI'}</span>
                  </button>
                  <button 
                    onClick={handleSend}
                    className="flex items-center space-x-2 px-6 py-2.5 bg-white text-green-700 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-green-50 transition-all shadow-xl hover:-translate-y-0.5"
                  >
                    <Send size={16} />
                    <span>SIŲSTI</span>
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div className="flex items-center bg-green-800/50 p-3 rounded-xl border border-white/10">
                  <span className="text-[9px] font-black text-white/40 uppercase tracking-widest w-14">Tema:</span>
                  <input 
                    className="flex-1 bg-transparent border-none outline-none text-xs font-bold text-white placeholder-white/30"
                    value={editableSubject}
                    onChange={e => setEditableSubject(e.target.value)}
                  />
                </div>
                <div className="flex items-center bg-green-800/50 p-3 rounded-xl border border-white/10">
                  <span className="text-[9px] font-black text-white/40 uppercase tracking-widest w-14">CC:</span>
                  <span className="text-xs font-bold text-white/60 truncate">{selectedTemplate.cc || 'Nepriskirta'}</span>
                </div>
              </div>
            </div>

            <div className="flex-1 p-8 relative bg-white overflow-hidden">
               {/* Decorative Background Icon */}
              <div className="absolute inset-0 opacity-[0.02] pointer-events-none select-none flex items-center justify-center">
                 <Mail size={320} />
              </div>

              <textarea 
                className="w-full h-full bg-transparent border-none outline-none resize-none text-slate-800 leading-relaxed font-bold text-base placeholder-slate-200 relative z-10 scrollbar-thin"
                value={editableBody}
                onChange={e => setEditableBody(e.target.value)}
                placeholder="Pradėkite rašyti laišką..."
              />
            </div>

            {/* Recommendation block matched with Intro design */}
            <div className="p-6 bg-blue-50 border-t border-blue-100 flex items-start space-x-4">
              <div className="bg-blue-600 p-2.5 rounded-xl text-white shadow-lg shadow-blue-200 flex-shrink-0">
                <Info size={20} />
              </div>
              <div className="text-[12px] text-blue-900 leading-relaxed">
                <strong className="block mb-0.5 font-black uppercase tracking-widest text-[9px] text-blue-800">REDAKCIJOS REKOMENDACIJA</strong>
                Prieš siųsdami laišką, būtinai pakeiskite tekstą skliausteliuose <code className="bg-blue-100 px-1 rounded font-black text-blue-700">[pvz., vardą]</code>. Paspaudus „SIŲSTI“, bus sukurta nauja žinutė su paruoštu tekstu.
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white border-2 border-dashed border-slate-100 rounded-[2rem] flex-1 flex flex-col items-center justify-center p-12 text-center group">
            <div className="bg-green-50 p-8 rounded-full mb-6 text-green-200 group-hover:bg-green-700 group-hover:text-white transition-all duration-700 transform group-hover:rotate-12 group-hover:scale-110">
              <Mail size={60} />
            </div>
            <h3 className="text-xl font-black text-slate-900 mb-2 tracking-tight uppercase">Pasirinkite šabloną</h3>
            <p className="text-slate-400 font-bold max-w-sm text-sm">
              Kairiajame sąraše pasirinkite reikiamą laišką, kad galėtumėte jį peržiūrėti, redaguoti ir greitai išsiųsti.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

