            { id: 'intro', label: 'Nuostatos' },
            { id: 'scenarios', label: 'Situacijos' },
            { id: 'schemes', label: 'Schemos' },
            { id: 'contacts', label: 'Specialistai' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => { handleTabChange(item.id); setIsMobileMenuOpen(false); }}
              className={`w-full text-left px-3 py-2 rounded-lg transition-colors flex items-center justify-between ${
                activeTab === item.id 
                  ? 'bg-green-50 text-green-700 font-black' 
                  : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <span className="text-xs">{item.label}</span>
            </button>
          ))}
          {/* External Link in Mobile Menu */}
          <button
            onClick={() => window.open('https://docs.google.com/document/d/171tuL9pKuBYC376oxjoqmdM9NSqfAsinSpHJoyk2m8Y/edit?tab=t.qschqx6t8w1', '_blank')}
