import { INITIAL_SPECIALISTS, INITIAL_TEMPLATES } from '../constants';

// --- Pagalbinės funkcijos audio kodavimui/dekodavimui ---
function encode(bytes: Uint8Array) {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

function createBlob(data: Float32Array): { data: string; mimeType: string } {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    int16[i] = data[i] * 32768;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

const STORAGE_KEY = 'vap_ai_live_transcripts_v2';

interface Message {
  role: 'user' | 'bot';
  text: string;
  type?: 'text' | 'voice';
}

interface AIAssistantProps {
  contextTab?: string;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ contextTab = 'dashboard' }) => {
  const [isActive, setIsActive] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isVoiceThinking, setIsVoiceThinking] = useState(false);
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [{ role: 'bot', text: 'Sveiki. Esu Jūsų emocinė pagalvėlė. Galite man rašyti arba paspausti mikrofoną ir pasikalbėti balsu apie tai, kaip jaučiatės.' }];
  });

  const [isMuted, setIsMuted] = useState(false);
  const [inputText, setInputText] = useState('');
  const [currentInput, setCurrentInput] = useState('');
  const [currentOutput, setCurrentOutput] = useState('');

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);

  // Padidintas konteksto gylis
  const getContextSpecificData = () => {
    switch (contextTab) {
      case 'contacts':
        return `Dabar vartotojas naršo specialistų kontaktus. Pasiūlyk pagalbą surandant tinkamą specialistą (pvz., soc. pedagogą ar psichologą). Specialistų sąrašas: ${INITIAL_SPECIALISTS.map(s => `${s.name} (${s.category})`).join(', ')}.`;
      case 'templates-link':
      case 'templates':
        return `Dabar vartotojas peržiūri laiškų šablonus. Pasiūlyk padėti suformuluoti laišką tėvams ar parinkti tinkamą toną. Turime šablonų tokioms kategorijoms: ${Array.from(new Set(INITIAL_TEMPLATES.map(t => t.category))).join(', ')}.`;
      case 'scenarios':
        return `Dabar vartotojas analizuoja elgesio valdymo situacijas. Pasiūlyk padėti interpretuoti konkretų mokinio elgesį pagal turimus algoritmus.`;
      case 'schemes':
        return `Dabar vartotojas žiūri pagalbos procesų schemas. Akcentuok nuoseklią veiksmų seką ir bendradarbiavimą su administracija.`;
      default:
        return `Vartotojas yra pagrindiniame apžvalgos lange. Teik bendrą emocinę paramą.`;
    }
  };

  const systemPrompt = `
    Esi „DI emocinė pagalvėlė“ Vilniaus Antakalnio progimnazijoje. 
    Tavo tikslas - teikti emocinę paramą mokytojams ir darbuotojams, remiantis "Pagalbasau.lt" principais: 
    empatija, raminimas, streso valdymas, savirūpą ir konstruktyvus problemų sprendimas.

    KONTEKSTAS: ${getContextSpecificData()}

    TAISYKLĖS:
    1. Kalbėk tik lietuviškai, šiltai, ramiai.
    2. Jei mokytojas pervargęs, pasiūlyk trumpą kvėpavimo pratimą arba "STOP" techniką.
    3. Atsakyk trumpai ir glaustai. 
    4. Niekada nemoralizuok. Būk kolegiškas palaikytojas.
    5. Jei situacija kritinė, primink apie specialistus arba 112.
  `;

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const stopSession = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.close();
      liveSessionRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(t => t.stop());
      micStreamRef.current = null;
    }
    for (const s of sourcesRef.current) s.stop();
    sourcesRef.current.clear();
    setIsActive(false);
    setIsVoiceThinking(false);
  };

  const startSession = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (!audioContextInRef.current) audioContextInRef.current = new AudioContext({ sampleRate: 16000 });
      if (!audioContextOutRef.current) audioContextOutRef.current = new AudioContext({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: systemPrompt,
        },
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              setCurrentInput(prev => prev + message.serverContent!.inputTranscription!.text);
              setIsVoiceThinking(true); 
            }
            if (message.serverContent?.outputTranscription) {
              setCurrentOutput(prev => prev + message.serverContent!.outputTranscription!.text);
              setIsVoiceThinking(false);
            }

            if (message.serverContent?.turnComplete) {
              setMessages(prev => [
                ...prev, 
                { role: 'user', text: currentInput || "(Balso užklausa)", type: 'voice' },
                { role: 'bot', text: currentOutput || "(Balso atsakymas)", type: 'voice' }
              ]);
              setCurrentInput('');
              setCurrentOutput('');
              setIsVoiceThinking(false);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && !isMuted) {
              const ctx = audioContextOutRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = buffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => sourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              for (const s of sourcesRef.current) s.stop();
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
              setIsVoiceThinking(false);
            }
          },
          onclose: () => setIsActive(false),
          onerror: (e) => {
            console.error(e);
            stopSession();
          }
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) {
      console.error(e);
      alert("Nepavyko pasiekti mikrofono.");
    }
  };

  const handleSendText = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!inputText.trim() || isGenerating) return;

    const userMsg = inputText.trim();
    setInputText('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg, type: 'text' }]);
    setIsGenerating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          { role: 'user', parts: [{ text: `Atsimink šias instrukcijas: ${systemPrompt}\n\nVartotojo žinutė: ${userMsg}` }] }
        ]
      });

      const botText = response.text || "Atsiprašau, įvyko klaida.";
      setMessages(prev => [...prev, { role: 'bot', text: botText, type: 'text' }]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, { role: 'bot', text: "Nepavyko gauti atsakymo. Bandykite dar kartą." }]);
    } finally {
      setIsGenerating(false);
    }
  };

  const clearHistory = () => {
    if (confirm("Ištrinti pokalbių istoriją?")) {
      setMessages([{ role: 'bot', text: 'Istorija išvalyta. Pasikalbėkime iš naujo.' }]);
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-4xl mx-auto bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in duration-700">
      {/* Header */}
      <div className={`p-8 transition-all duration-500 ${isActive ? 'bg-green-700' : 'bg-slate-900'} text-white relative`}>
        <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none">
          <Sparkles size={140} />
        </div>

        <div className="relative z-10 flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border transition-all duration-500 ${isActive ? 'bg-white text-green-700 border-white/20' : 'bg-white/10 text-amber-400 border-white/10'}`}>
              {isActive ? <div className="animate-pulse"><Waves size={28} /></div> : <Heart size={28} />}
            </div>
            <div>
              <h2 className="text-2xl font-[900] tracking-tight uppercase leading-tight">DI EMOCINĖ PAGALVĖLĖ</h2>
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-white/40">
                Pagalba realiu laiku • {contextTab === 'dashboard' ? 'Apžvalga' : contextTab === 'contacts' ? 'Kontaktai' : 'Kontekstas aktyvus'}
              </p>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            <button 
              onClick={clearHistory}
              className="p-3 bg-white/5 hover:bg-rose-500/20 rounded-xl transition-all border border-white/5 text-white/60 hover:text-rose-200"
              title="Valyti istoriją"
            >
              <Trash2 size={20} />
            </button>
            <button 
              onClick={() => setIsMuted(!isMuted)}
              className={`p-3 rounded-xl transition-all border ${isMuted ? 'bg-rose-500/20 text-rose-400 border-rose-500/30' : 'bg-white/5 text-white border-white/10 hover:bg-white/10'}`}
              title={isMuted ? 'Garsas išjungtas' : 'Garsas įjungtas'}
            >
              {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
            </button>
          </div>
        </div>
      </div>

      {/* Messages area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/30 scrollbar-thin relative">
        {/* Voice Feedback Animation Layers */}
        {isActive && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 pointer-events-none flex flex-col items-center">
             {!isVoiceThinking ? (
                <div className="bg-green-700 text-white px-6 py-2 rounded-full shadow-2xl flex items-center space-x-3 border border-white/20 animate-in slide-in-from-top-4 duration-300">
                  <div className="flex space-x-1 items-end h-4">
                    <div className="w-1 bg-white rounded-full animate-wave-sm h-2"></div>
                    <div className="w-1 bg-white rounded-full animate-wave h-4"></div>
                    <div className="w-1 bg-white rounded-full animate-wave-sm h-3"></div>
                    <div className="w-1 bg-white rounded-full animate-wave h-4"></div>
                  </div>
                  <span className="text-[10px] font-black uppercase tracking-widest">Klausausi Jūsų...</span>
                </div>
             ) : (
                <div className="bg-amber-500 text-white px-6 py-2 rounded-full shadow-2xl flex items-center space-x-3 border border-white/20 animate-in slide-in-from-top-4 duration-300">
                  <BrainCircuit size={16} className="animate-spin duration-[2000ms]" />
                  <span className="text-[10px] font-black uppercase tracking-widest">Apdoroju mintis...</span>
                </div>
             )}
          </div>
        )}

        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2`}>
            <div className={`flex items-start space-x-3 max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 shadow-sm border ${msg.role === 'user' ? 'bg-slate-900 text-white border-slate-800' : 'bg-white text-green-700 border-green-100'}`}>
                {msg.role === 'user' ? <Zap size={14} /> : <Coffee size={14} />}
              </div>
              <div className={`p-4 rounded-2xl shadow-sm text-[13.5px] font-bold leading-relaxed ${msg.role === 'user' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}`}>
                {msg.text}
                {msg.type === 'voice' && <span className="block mt-1 text-[8px] uppercase tracking-widest opacity-30">Balso transkripcija</span>}
