        }
        @keyframes wave-sm {
          0%, 100% { height: 4px; }
          50% { height: 10px; }
        }
        .animate-wave { animation: wave 1s ease-in-out infinite; }
        .animate-wave-sm { animation: wave-sm 0.8s ease-in-out infinite; }
      `}</style>
    </div>
  );
};

