interface AIAssistantProps {
  contextTab?: string;
}

const AIAssistant: React.FC<AIAssistantProps> = ({ contextTab = 'dashboard' }) => {
  const [isActive, setIsActive] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isVoiceThinking, setIsVoiceThinking] = useState(false);
  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : [{ role: 'bot', text: 'Sveiki. Esu Jūsų emocinė pagalvėlė. Galite man rašyti arba pasikalbėti balsu. Matau, kad šiuo metu domitės ' + (contextTab === 'contacts' ? 'specialistų kontaktais' : contextTab === 'templates' ? 'laiškų šablonais' : 'mokyklos procesais') + '. Kuo galėčiau padėti?' }];
  });

  const [isMuted, setIsMuted] = useState(false);
  const [inputText, setInputText] = useState('');
  const [currentInput, setCurrentInput] = useState('');
  const [currentOutput, setCurrentOutput] = useState('');

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const liveSessionRef = useRef<any>(null);
  const audioContextInRef = useRef<AudioContext | null>(null);
  const audioContextOutRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const micStreamRef = useRef<MediaStream | null>(null);

  const getContextSpecificData = () => {
    switch (contextTab) {
      case 'contacts':
        return `Vartotojas naršo specialistų kontaktus. Specialistai: ${INITIAL_SPECIALISTS.map(s => `${s.name} (${s.category}, kab. ${s.office})`).join(', ')}.`;
      case 'templates':
        return `Vartotojas žiūri laiškų šablonus. Kategorijos: ${Array.from(new Set(INITIAL_TEMPLATES.map(t => t.category))).join(', ')}.`;
      case 'scenarios':
        return `Vartotojas analizuoja elgesio valdymo situacijas (UAK protokolas, SOS algoritmai).`;
      default:
        return `Vartotojas yra pagrindiniame lange.`;
    }
  };

  const systemPrompt = `
    Esi „DI emocinė pagalvėlė“ Vilniaus Antakalnio progimnazijoje. 
    Teik emocinę paramą mokytojams. Būk empatiškas, ramus, kolegiškas.
    KONTEKSTAS: ${getContextSpecificData()}
    Jei klausiama apie specialistus, naudok pateiktą sąrašą. 
    Atsakymai lietuviški, trumpi, raminantys.
  `;

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const stopSession = () => {
    if (liveSessionRef.current) {
      liveSessionRef.current.close();
      liveSessionRef.current = null;
    }
    if (micStreamRef.current) {
      micStreamRef.current.getTracks().forEach(t => t.stop());
      micStreamRef.current = null;
    }
    for (const s of sourcesRef.current) s.stop();
    sourcesRef.current.clear();
    setIsActive(false);
    setIsVoiceThinking(false);
  };

  const startSession = async () => {
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      if (!audioContextInRef.current) audioContextInRef.current = new AudioContext({ sampleRate: 16000 });
      if (!audioContextOutRef.current) audioContextOutRef.current = new AudioContext({ sampleRate: 24000 });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      micStreamRef.current = stream;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: systemPrompt,
        },
        callbacks: {
          onopen: () => {
            setIsActive(true);
            const source = audioContextInRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextInRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(session => session.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextInRef.current!.destination);
          },
          onmessage: async (m: LiveServerMessage) => {
            if (m.serverContent?.inputTranscription) {
              setCurrentInput(p => p + m.serverContent!.inputTranscription!.text);
              setIsVoiceThinking(true); 
            }
            if (m.serverContent?.outputTranscription) {
              setCurrentOutput(p => p + m.serverContent!.outputTranscription!.text);
              setIsVoiceThinking(false);
            }
            if (m.serverContent?.turnComplete) {
              setMessages(p => [...p, { role: 'user', text: currentInput || "...", type: 'voice' }, { role: 'bot', text: currentOutput || "...", type: 'voice' }]);
              setCurrentInput(''); setCurrentOutput(''); setIsVoiceThinking(false);
            }
            const audio = m.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audio && !isMuted) {
              const ctx = audioContextOutRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const buffer = await decodeAudioData(decode(audio), ctx, 24000, 1);
              const s = ctx.createBufferSource();
              s.buffer = buffer; s.connect(ctx.destination);
              s.addEventListener('ended', () => sourcesRef.current.delete(s));
              s.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(s);
            }
            if (m.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear();
              nextStartTimeRef.current = 0; setIsVoiceThinking(false);
            }
          },
          onclose: () => setIsActive(false),
          onerror: () => stopSession()
        }
      });
      liveSessionRef.current = await sessionPromise;
    } catch (e) { alert("Mikrofono prieiga būtina."); }
  };

  const handleSendText = async (customPrompt?: string) => {
    const textToSend = customPrompt || inputText.trim();
    if (!textToSend || isGenerating) return;

    setInputText('');
    setMessages(prev => [...prev, { role: 'user', text: textToSend, type: 'text' }]);
    setIsGenerating(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: `Kontekstas: ${systemPrompt}\n\nUžklausa: ${textToSend}` }] }]
      });
      setMessages(prev => [...prev, { role: 'bot', text: response.text || "...", type: 'text' }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'bot', text: "Atsiprašau, ryšio sutrikimas." }]);
    } finally { setIsGenerating(false); }
  };

  const activePrompts = QUICK_PROMPTS[contextTab] || QUICK_PROMPTS.dashboard;

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] max-w-4xl mx-auto bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 overflow-hidden animate-in fade-in duration-700">
      {/* Dynamic Header */}
      <div className={`p-8 transition-all duration-700 ${isActive ? 'bg-green-700' : 'bg-slate-900'} text-white relative overflow-hidden`}>
        <div className={`absolute -inset-1 bg-gradient-to-r from-green-400/20 to-blue-500/20 blur-2xl transition-opacity duration-1000 ${isActive ? 'opacity-100' : 'opacity-0'}`} />
        <div className="relative z-10 flex items-center justify-between">
          <div className="flex items-center space-x-5">
            <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center border transition-all duration-500 ${isActive ? 'bg-white text-green-700 border-white/40 shadow-[0_0_20px_rgba(255,255,255,0.4)]' : 'bg-white/10 text-amber-400 border-white/10'}`}>
              {isActive ? <Waves className="animate-pulse" size={32} /> : <Sparkles size={32} />}
            </div>
            <div>
              <h2 className="text-2xl font-black tracking-tighter uppercase leading-none">EMOCINĖ PAGALVĖLĖ</h2>
              <div className="flex items-center space-x-2 mt-2">
                <div className={`w-2 h-2 rounded-full ${isActive ? 'bg-green-400 animate-ping' : 'bg-slate-500'}`} />
                <p className="text-[10px] font-black uppercase tracking-widest text-white/50">
                  {isActive ? 'Aktyvus pokalbis balsu' : 'Pasiruošusi padėti'}
                </p>
              </div>
            </div>
          </div>
          <div className="flex space-x-2">
            <button onClick={() => setIsMuted(!isMuted)} className={`p-4 rounded-2xl transition-all border ${isMuted ? 'bg-rose-500/20 text-rose-400 border-rose-500/30' : 'bg-white/5 text-white border-white/10 hover:bg-white/20'}`}>
              {isMuted ? <VolumeX size={20} /> : <Volume2 size={20} />}
            </button>
            <button onClick={() => { if(confirm("Išvalyti?")) { setMessages([]); localStorage.removeItem(STORAGE_KEY); } }} className="p-4 bg-white/5 hover:bg-rose-500/20 rounded-2xl transition-all border border-white/10 text-white/60">
              <Trash2 size={20} />
            </button>
          </div>
        </div>
      </div>

      {/* Messages & Context Area */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50 scrollbar-thin relative">
        {/* Quick Prompts - Contextual */}
        <div className="flex overflow-x-auto pb-4 gap-3 no-scrollbar">
          {activePrompts.map((p, i) => (
            <button
              key={i}
              onClick={() => handleSendText(p.prompt)}
              className="flex-shrink-0 flex items-center space-x-3 px-5 py-3 bg-white border border-slate-200 rounded-2xl text-[11px] font-black text-slate-700 hover:border-green-500 hover:text-green-700 transition-all shadow-sm hover:shadow-md group"
            >
              <div className="p-2 bg-slate-50 rounded-lg group-hover:bg-green-50 transition-colors">
                {p.icon}
              </div>
              <span className="uppercase tracking-wider">{p.label}</span>
              <ArrowUpRight size={14} className="opacity-30 group-hover:opacity-100" />
            </button>
          ))}
        </div>

        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
            <div className={`flex items-start space-x-3 max-w-[85%] ${m.role === 'user' ? 'flex-row-reverse space-x-reverse' : ''}`}>
              <div className={`w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0 shadow-sm border ${m.role === 'user' ? 'bg-slate-900 text-white' : 'bg-white text-green-700 border-green-100'}`}>
                {m.role === 'user' ? <Zap size={16} /> : <Coffee size={16} />}
              </div>
              <div className={`p-5 rounded-3xl shadow-sm text-sm font-bold leading-relaxed ${m.role === 'user' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white text-slate-800 border border-slate-100 rounded-tl-none'}`}>
                {m.text}
                {m.type === 'voice' && <span className="block mt-2 text-[8px] uppercase tracking-widest opacity-30 italic">Balso transkripcija</span>}
              </div>
            </div>
          </div>
        ))}

        {isGenerating && (
          <div className="flex justify-start animate-pulse">
            <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex items-center space-x-3">
              <Loader2 className="animate-spin text-green-600" size={20} />
              <span className="text-[11px] font-black uppercase tracking-widest text-slate-400">Pagalvėlė galvoja...</span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input / Control Bar */}
      <div className="p-8 bg-white border-t border-slate-100">
        <div className="flex items-end space-x-4">
          <div className="flex-1 relative">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendText(); } }}
              placeholder="Rašykite čia..."
              className="w-full bg-slate-50 border border-slate-200 rounded-3xl px-6 py-4 text-sm font-bold outline-none focus:border-green-600 focus:ring-4 focus:ring-green-600/5 transition-all resize-none max-h-32"
              rows={1}
            />
            <button onClick={() => handleSendText()} disabled={!inputText.trim() || isGenerating} className={`absolute right-4 bottom-3 p-3 rounded-2xl transition-all ${inputText.trim() ? 'bg-green-700 text-white shadow-xl hover:bg-green-800' : 'bg-slate-100 text-slate-300'}`}>
              <Send size={20} />
            </button>
          </div>
          <button onClick={isActive ? stopSession : startSession} className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all shadow-xl relative group ${isActive ? 'bg-rose-500 text-white animate-pulse' : 'bg-green-700 text-white hover:bg-green-800'}`}>
            {isActive ? <MicOff size={24} /> : <Mic size={24} />}
            {isActive && <div className="absolute -inset-2 border-4 border-rose-500/20 rounded-[2rem] animate-ping" />}
          </button>
        </div>
      </div>
    </div>
  );
};

