    bg: 'bg-blue-600', color: 'text-blue-600', light: 'bg-blue-50',
    icon: <Users size={24} />
  },
  [SpecialistCategory.SVEIKATA]: { 
    bg: 'bg-rose-500', color: 'text-rose-500', light: 'bg-rose-50',
