                  {isActive ? 'Balso ryšys įjungtas' : 'Tekstinis ryšys'}
                </div>
                <div className={`w-2 h-2 rounded-full transition-colors ${isActive ? 'bg-emerald-400 animate-pulse' : 'bg-slate-500'}`} />
