                  {contextTab === 'dashboard' ? 'Apžvalga' : contextTab === 'contacts' ? 'Kontaktai' : contextTab === 'scenarios' ? 'Situacijos' : contextTab === 'intro' ? 'Nuostatos' : contextTab === 'schemes' ? 'Schemos' : contextTab === 'emergency' ? 'Pagalba' : 'Kontekstas'}
                </p>
