                onKeyDown={(e) => { if(e.key === 'Enter') handleSendText(); }}
                placeholder="Rašykite arba užduokite klausimą..."
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl px-6 py-4 text-[15px] font-bold outline-none focus:border-emerald-600 focus:bg-white transition-all"
              />
              <button 
                onClick={() => handleSendText()} 
                disabled={!inputText.trim() || isGenerating} 
                className={`absolute right-2 top-2 p-3 rounded-2xl transition-all transform active:scale-90 ${inputText.trim() ? 'bg-emerald-700 text-white shadow-lg hover:bg-emerald-800' : 'text-slate-300 cursor-not-allowed'}`}
              >
                <Send size={20} />
              </button>
            </div>

            {/* Multimedia Controls */}
            <div className="flex items-center space-x-3">
              <button 
                onClick={() => setIsMuted(!isMuted)}
                className={`w-14 h-14 rounded-3xl flex items-center justify-center transition-all border-2 ${isMuted ? 'bg-rose-50 text-rose-600 border-rose-100 shadow-inner' : 'bg-slate-50 text-slate-500 hover:bg-slate-100 border-slate-100 hover:border-slate-200'}`}
                title={isMuted ? "Garsas išjungtas" : "Garsas įjungtas"}
              >
                {isMuted ? <VolumeX size={22} /> : <Volume2 size={22} />}
              </button>

              <button 
                onClick={isActive ? stopSession : startSession} 
                className={`w-14 h-14 rounded-3xl flex items-center justify-center transition-all relative border-2 ${isActive ? 'bg-rose-600 text-white border-rose-500 shadow-xl shadow-rose-200' : 'bg-emerald-700 text-white border-emerald-600 hover:bg-emerald-800 hover:scale-105'}`}
                title={isActive ? "Sustabdyti balsą" : "Kalbėti balsu"}
              >
                {isActive ? <MicOff size={22} /> : <Mic size={22} />}
                {isActive && (
                  <div className="absolute -inset-2 border-2 border-rose-400/20 rounded-[2rem] animate-ping" />
                )}
              </button>
            </div>
          </div>

          {/* Active Status / Transcription bar */}
          {isActive && (currentInput || currentOutput) && (
            <div className="p-4 bg-emerald-50 rounded-3xl border border-emerald-100 animate-in fade-in slide-in-from-bottom-2 duration-500 flex items-start space-x-3">
               <div className="bg-emerald-600 p-2 rounded-xl text-white shadow-sm mt-0.5">
                  <Waves size={16} className="animate-pulse" />
               </div>
               <div className="flex-1">
                  <div className="flex items-center justify-between mb-1">
                     <span className="text-[9px] font-black uppercase text-emerald-800 tracking-[0.15em]">DI Ryšys aktyvus</span>
                     <div className="flex space-x-0.5">
                        <div className="w-1 h-2 bg-emerald-400 animate-bounce" style={{animationDelay: '0s'}}></div>
                        <div className="w-1 h-3 bg-emerald-400 animate-bounce" style={{animationDelay: '0.1s'}}></div>
                        <div className="w-1 h-2 bg-emerald-400 animate-bounce" style={{animationDelay: '0.2s'}}></div>
                     </div>
                  </div>
                  <p className="text-[13px] font-bold text-emerald-900 leading-snug">
                    {currentOutput || currentInput || "Klausau Jūsų..."}
                  </p>
               </div>
            </div>
          )}
        </div>
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

